IF EXISTS (SELECT name FROM master.dbo.sysdatabases WHERE name = N'VTE')
	DROP DATABASE [VTE]
GO
DECLARE @device_directory NVARCHAR(520)
SELECT @device_directory = SUBSTRING(filename, 1, CHARINDEX(N'master.mdf', LOWER(filename)) - 1)
FROM master.dbo.sysaltfiles WHERE dbid = 1 AND fileid = 1
/****** Object:  Database [KenoBingo]    Script Date: 07/13/2009 15:22:26 ******/
EXECUTE (N'CREATE DATABASE VTE
  ON PRIMARY (NAME = N''VTE'', FILENAME = N''' + @device_directory + N'VTE.mdf'')
  LOG ON (NAME = N''VTE_log'',  FILENAME = N''' + @device_directory + N'VTE_log.ldf'')')
GO
EXEC dbo.sp_dbcmptlevel @dbname=N'VTE', @new_cmptlevel=90
GO
IF (1 = FULLTEXTSERVICEPROPERTY('IsFullTextInstalled'))
begin
EXEC [VTE].[dbo].[sp_fulltext_database] @action = 'enable'
end
GO
