/****** Object:  StoredProcedure [dbo].[updateCustomerVehicleRelationsHistor]    Script Date: 08/06/2009 13:09:54 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za UPDATE na zapis

CREATE PROC [dbo].[updateCustomerVehicleRelationsHistor]
		@Id bigint,
		@IdNewCustomerVehicleRelation bigint,
		@IdOldCustomerVehicleRelation bigint,
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [CustomerVehicleRelationsHistory]
		SET
		IdNewCustomerVehicleRelation = @idnewcustomervehiclerelation,
		IdOldCustomerVehicleRelation = @idoldcustomervehiclerelation
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [CustomerVehicleRelationsHistory] WHERE ID=@id
	RETURN
GO
