/****** Object:  StoredProcedure [dbo].[addCustomerVehicleRelationsHistor]    Script Date: 08/06/2009 13:09:54 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za dodavanje na nov zapis

CREATE PROC [dbo].[addCustomerVehicleRelationsHistor]
		@IdNewCustomerVehicleRelation bigint,
		@IdOldCustomerVehicleRelation bigint,
		@NewId bigint output,
		@newLastChanged timestamp output
AS
    INSERT INTO [CustomerVehicleRelationsHistory]
		(
		IdNewCustomerVehicleRelation,
		IdOldCustomerVehicleRelation
		)
		VALUES
		(
		@IdNewCustomerVehicleRelation,
		@IdOldCustomerVehicleRelation
		)
	
	SELECT @NewId = Id, @newLastChanged = LastChanged
	FROM [CustomerVehicleRelationsHistory] WHERE Id=SCOPE_IDENTITY()
	RETURN
GO
