SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za dodavanje na nov zapis

CREATE PROC [dbo].[addVehicleTyre]
		@IdVehicle int,
		@IdTireType int,
		@NewId int output,
		@newLastChanged timestamp output
AS
    INSERT INTO [Vehicle.Tyres]
		(
		IdVehicle,
		IdTireType
		)
		VALUES
		(
		@IdVehicle,
		@IdTireType
		)
	
	SELECT @NewId = Id, @newLastChanged = LastChanged
	FROM [Vehicle.Tyres] WHERE Id=SCOPE_IDENTITY()
	RETURN
GO
