CREATE PROC [dbo].[updateVehicleDisabledField]
		@Id int,
		@IdCategory int,
		@FieldName nvarchar(250),
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [VehicleDisabledFields]
		SET
		IdCategory = @idcategory,
		FieldName = @fieldname
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [VehicleDisabledFields] WHERE ID=@id
	RETURN
GO
