/****** Object:  StoredProcedure [dbo].[printTrafficLicenceById]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[printTrafficLicenceById] 
	-- Add the parameters for the stored procedure here
	@id bigint
AS
SELECT     dbo.DocumentsTrafficLicences.Id, dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation, dbo.CustomerVehiclesRelations.IdCustomer, 
                      dbo.CustomerVehiclesRelations.IdVehicle, dbo.DocumentsTrafficLicences.IdTehnicalExamOrganizationsIssuedBy, 
                      dbo.RegistrationIssuers.IssuerName, dbo.DocumentsTrafficLicences.TrafficLicenceNumber, dbo.DocumentsTrafficLicences.MadeDate, 
                      dbo.DocumentsTrafficLicences.EndDate, dbo.DocumentsTrafficLicences.Note, dbo.Customers.MB, dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName, dbo.Customers.IdLivingAddress, dbo.Streets.StreetName, dbo.Customers.LivingAddressNumber, 
                      dbo.Vehicles.IdVehicleCategoryForPayments, dbo.VehicleCategoryForPayments.Name AS VehicleCategoryForPaymentName, 
                      dbo.Vehicles.IdVehicleModel, dbo.VehicleModel.ModelName, dbo.VehicleModel.IdVehicleMaker, dbo.VehicleMakers.CompanyName AS VehicleMaker, 
                      dbo.Vehicles.ShellNumber, dbo.Vehicles.EngineNumber, dbo.Vehicles.MakeDate, dbo.Vehicles.EnginePower, dbo.Vehicles.EngineTorque, 
                      dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.EnginePowerOutPut, dbo.VehicleCategoryForPayments.Code AS VehcilceCategoryForPaymentCode,
                       dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, dbo.Vehicles.NumberOfSeats, dbo.Vehicles.NumberOfStandingSeats, 
                      dbo.Vehicles.NumberOfLieingSeats, dbo.VehicleBodytype.BodytypeDescriprion, dbo.VehicleBodytype.OldBodytypeDescription, 
                      dbo.VehicleBodytype.BodytypeCode, dbo.Vehicles.IdVehicleBodyType, dbo.Vehicles.IdVehicleUse, dbo.VehicleUse.UseDescription, 
                      dbo.Vehicles.IdPrimaryColor, dbo.Colors.ColorCode, dbo.Colors.ColorDescription, dbo.Vehicles.IdSecondaryColor, 
                      Colors_1.ColorCode AS SecondaryColorCode, Colors_1.ColorDescription AS SecondaryColorDescription, dbo.Vehicles.NumberOfDoors, 
                      dbo.Vehicles.NumberOfAxis, dbo.Vehicles.IdVehicleCategories, dbo.VehicleCategories.CategoryCode, dbo.VehicleCategories.CategoryName, dbo.VehicleEngineTypes.EngineTypeCode
FROM         dbo.Streets RIGHT OUTER JOIN
                      dbo.DocumentsTrafficLicences INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.RegistrationIssuers ON dbo.DocumentsTrafficLicences.IdTehnicalExamOrganizationsIssuedBy = dbo.RegistrationIssuers.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id LEFT OUTER JOIN dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id INNER JOIN
                      dbo.VehicleCategoryForPayments ON dbo.Vehicles.IdVehicleCategoryForPayments = dbo.VehicleCategoryForPayments.Id INNER JOIN
                      dbo.VehicleCategories ON dbo.Vehicles.IdVehicleCategories = dbo.VehicleCategories.Id ON 
                      dbo.Streets.Id = dbo.Customers.IdLivingAddress LEFT OUTER JOIN
                      dbo.VehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id ON 
                      dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id LEFT OUTER JOIN
                      dbo.VehicleBodytype ON dbo.Vehicles.IdVehicleBodyType = dbo.VehicleBodytype.Id LEFT OUTER JOIN
                      dbo.Colors ON dbo.Vehicles.IdPrimaryColor = dbo.Colors.Id LEFT OUTER JOIN
                      dbo.Colors AS Colors_1 ON dbo.Vehicles.IdSecondaryColor = Colors_1.Id LEFT OUTER JOIN
                      dbo.VehicleUse ON dbo.Vehicles.IdVehicleUse = dbo.VehicleUse.Id 
                      WHERE (dbo.DocumentsTrafficLicences.Id=@id) AND (dbo.DocumentsTrafficLicences.Active=1)
GO
