/****** Object:  StoredProcedure [dbo].[getPaymentCatalog]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[getPaymentCatalog] 
AS
SELECT
	dbo.PaymentCategories.Id AS IdPaymentCategory,
	dbo.PaymentItems.Id AS IdPaymentItem, 
	dbo.PaymentItemParametars.Id AS IdPaymentParametar, 
	dbo.PaymentCategories.IdDDV, 
	dbo.PaymentCategories.IdCalculationItem, 
	dbo.DDVCatalog.DDVName, 
	dbo.DDVCatalog.DDVValue, 
	dbo.PaymentCategories.CategoryName, 
	dbo.PaymentCategories.AllowDiscount,
	dbo.PaymentCategories.TrigerdByRequest, 
	dbo.PaymentCategories.TrigerdByTechnicalExam, 
	dbo.PaymentCategories.TrigerdByTrafficLicence, 
	dbo.PaymentCategories.TrigerdByPremisionForVehicle, 
	dbo.PaymentCategories.TrigerdByInternationalDrivierLicence,
	dbo.PaymentCategories.TrigerdByIrregularTechnicalExam,
	dbo.VehicleCategoryForPayments.Code AS VehicleCategoriesForPaymantCode, 
	dbo.VehicleCategoryForPayments.Name AS VehicleCategoriesForPaymantName, 
	dbo.PaymentItems.IdVehicleCategoryForPayments, 
	dbo.PaymentItems.ItemName, 
	dbo.PaymentItemParametars.PrametarName, 
	dbo.PaymentItemParametars.VehicleField, 
	dbo.PaymentItemParametars.ParametarFrom, 
	dbo.PaymentItemParametars.ParametarTo, 
	dbo.PaymentItemParametars.Price, 
	dbo.PaymentItemParametars.IsOptional,
	dbo.PaymentCategories.VisibleOrder
FROM         
	dbo.VehicleCategoryForPayments INNER JOIN
	dbo.PaymentItems ON dbo.VehicleCategoryForPayments.Id = dbo.PaymentItems.IdVehicleCategoryForPayments INNER JOIN
	dbo.PaymentCategories INNER JOIN
	dbo.DDVCatalog ON dbo.PaymentCategories.IdDDV = dbo.DDVCatalog.Id ON 
	dbo.PaymentItems.IdPymentCategory = dbo.PaymentCategories.Id INNER JOIN
	dbo.PaymentItemParametars ON dbo.PaymentItems.Id = dbo.PaymentItemParametars.IdPaymentItem
WHERE
	(dbo.PaymentCategories.Active = 1) AND 
	(dbo.PaymentItems.Active = 1) AND 
	(dbo.PaymentItemParametars.Active = 1)
GO
/****** Object:  StoredProcedure [dbo].[printVehiclePivotReport]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Ivan
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[printVehiclePivotReport]

AS
SELECT     dbo.Vehicles.EngineNumber, dbo.Vehicles.ColorCode, dbo.Vehicles.EnginePower, dbo.Vehicles.EngineTorque, dbo.Vehicles.EngineTorqueUnderGass, 
                      dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.EnginePowerOutPut, dbo.Vehicles.ShellNumber, dbo.Vehicles.MakeDate, 
                      dbo.Vehicles.NumberOfDoors, dbo.Vehicles.NumberOfSeats, dbo.Vehicles.NumberOfStandingSeats, dbo.Vehicles.NumberOfLieingSeats, 
                      dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, dbo.Vehicles.NumberOfAxis, dbo.Vehicles.PropulsionAxis, 
                      dbo.Vehicles.NumberOfWheels, dbo.Vehicles.NumberOfPropulsionWheels, dbo.Vehicles.VehicleSizeHight, dbo.Vehicles.VehicleSizeWidth, 
                      dbo.Vehicles.VehicleSizeLength, dbo.VehicleBodytype.BodytypeCode, dbo.VehicleBodytype.BodytypeDescriprion, 
                      dbo.VehicleCategories.CategoryCode, dbo.VehicleCategories.CategoryName, dbo.VehicleEngineEcoProgram.EcoProgram, 
                      dbo.VehicleEngineEcoProgram.TechincalDescription, dbo.VehicleEngineTypes.EngineTypeCode, 
                      dbo.VehicleEngineTypes.TechincalDescription AS EngineTechincalDescription, dbo.Vehicles.IdPrimaryColor, dbo.Vehicles.IdSecondaryColor, 
                      dbo.VehicleModel.ModelName, dbo.VehicleModel.YearOfBeginingProduction, dbo.VehicleModel.YearOfEndingProduction, 
                      dbo.VehicleMakers.CompanyName, dbo.VehicleMakers.CompanyTrademark, dbo.VehicleCategoryForPayments.Code, 
                      dbo.VehicleCategoryForPayments.Name, dbo.Vehicles.IdEnginePowerSource, dbo.Vehicles.IdEngineSecondPowerSource, dbo.Vehicles.Id

FROM         dbo.VehicleMakers INNER JOIN
                      dbo.VehicleModel ON dbo.VehicleMakers.Id = dbo.VehicleModel.IdVehicleMaker RIGHT OUTER JOIN
                      dbo.Vehicles ON dbo.VehicleModel.Id = dbo.Vehicles.IdVehicleModel LEFT OUTER JOIN
                      dbo.VehicleEngineEcoProgram ON dbo.Vehicles.IdEngineEcoProgram = dbo.VehicleEngineEcoProgram.Id LEFT OUTER JOIN
                      dbo.VehicleCategoryForPayments ON dbo.Vehicles.IdVehicleCategoryForPayments = dbo.VehicleCategoryForPayments.Id LEFT OUTER JOIN
                      dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id LEFT OUTER JOIN
                      dbo.VehicleCategories ON dbo.Vehicles.IdVehicleCategories = dbo.VehicleCategories.Id LEFT OUTER JOIN
                      dbo.VehicleBodytype ON dbo.Vehicles.IdVehicleBodyType = dbo.VehicleBodytype.Id
where dbo.Vehicles.Active = 1
GO
