-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[printVehcile] 
	-- Add the parameters for the stored procedure here
	@id bigint
AS
SELECT     dbo.Vehicles.Id, dbo.Vehicles.IdVehicleBodyType, dbo.Vehicles.IdVehicleCategories, dbo.VehicleCategories.CategoryCode, 
                      dbo.VehicleCategories.CategoryName, dbo.VehicleBodytype.BodytypeCode, dbo.VehicleBodytype.BodytypeDescriprion, 
                      dbo.VehicleBodytype.OldBodytypeDescription, dbo.VehicleCategories.OldCategoryName, dbo.Vehicles.IdVehicleCategoryForPayments, 
                      dbo.VehicleCategoryForPayments.Code AS CategoryForPaymentsCode, dbo.VehicleCategoryForPayments.Name AS CategoryForPaymentsName, 
                      dbo.Vehicles.IdVehicleUse, dbo.VehicleUse.UseDescription, dbo.Vehicles.IdVehicleModel, dbo.VehicleModel.ModelCode, 
                      dbo.VehicleModel.ModelName, dbo.VehicleModel.IdVehicleMaker, dbo.VehicleMakers.CompanyName AS VehicleMaker, dbo.Vehicles.IdPrimaryColor, 
                      dbo.Vehicles.IdSecondaryColor, dbo.Colors.ColorCode, dbo.Colors.ColorDescription, Colors_1.ColorCode AS ColorCodeSecondary, 
                      Colors_1.ColorDescription AS ColorDescriptionSecondary, dbo.Vehicles.IdEngineType, dbo.VehicleEngineTypes.EngineTypeCode, 
                      dbo.VehicleEngineTypes.TechincalDescription AS VehicleEngineTypeTechincalDescription, dbo.Vehicles.EngineNumber, dbo.Vehicles.EnginePower, 
                      dbo.Vehicles.EnginePowerOutPut, dbo.Vehicles.EngineTorque, dbo.Vehicles.ShellNumber, dbo.Vehicles.MakeDate, dbo.Vehicles.NumberOfDoors, 
                      dbo.Vehicles.NumberOfSeats, dbo.Vehicles.NumberOfStandingSeats, dbo.Vehicles.NumberOfLieingSeats, dbo.Vehicles.EmptyWaight, 
                      dbo.Vehicles.MaximunAllowedWaight, dbo.Vehicles.NumberOfAxis, dbo.Vehicles.PropulsionAxis, dbo.Vehicles.NumberOfWheels, 
                      dbo.Vehicles.NumberOfPropulsionWheels, dbo.Vehicles.VehicleSizeHight, dbo.Vehicles.VehicleSizeWidth, dbo.Vehicles.VehicleSizeLength, 
                      dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.IdMadeCountry, dbo.Countries.CountryName AS MadeCountry, dbo.Vehicles.IdEnginePowerSource, 
                      VehicleEnginePowerSourceTypes_1.PowerSourceName, dbo.Vehicles.Hook, dbo.Vehicles.Vitlo, dbo.Vehicles.IdEngineSecondPowerSource, 
                      dbo.VehicleEnginePowerSourceTypes.PowerSourceName AS PowerSourceNameSecond,
                      dbo.Vehicles.VehicleModelAdding 
FROM         dbo.VehicleEnginePowerSourceTypes AS VehicleEnginePowerSourceTypes_1 RIGHT OUTER JOIN
                      dbo.Vehicles INNER JOIN
                      dbo.VehicleCategories ON dbo.Vehicles.IdVehicleCategories = dbo.VehicleCategories.Id INNER JOIN
                      dbo.VehicleBodytype ON dbo.Vehicles.IdVehicleBodyType = dbo.VehicleBodytype.Id INNER JOIN
                      dbo.VehicleMakers INNER JOIN
                      dbo.VehicleModel ON dbo.VehicleMakers.Id = dbo.VehicleModel.IdVehicleMaker ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id ON 
                      VehicleEnginePowerSourceTypes_1.Id = dbo.Vehicles.IdEnginePowerSource LEFT OUTER JOIN
                      dbo.Countries ON dbo.Vehicles.IdMadeCountry = dbo.Countries.Id LEFT OUTER JOIN
                      dbo.VehicleCategoryForPayments ON dbo.Vehicles.IdVehicleCategoryForPayments = dbo.VehicleCategoryForPayments.Id LEFT OUTER JOIN
                      dbo.VehicleEnginePowerSourceTypes ON dbo.Vehicles.IdEngineSecondPowerSource = dbo.VehicleEnginePowerSourceTypes.Id LEFT OUTER JOIN
                      dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id LEFT OUTER JOIN
