CREATE PROCEDURE [dbo].[printPaymentDocumetnByIdDocumetn] 
	-- Add the parameters for the stored procedure here
	@idDocument int
AS
SELECT     dbo.PaymentDocuments.Id AS DocumentID, dbo.PaymentDocuments.DatePay AS DocumentDate, 
                      dbo.PaymentDocuments.DateRequired AS RequiredDate, dbo.PaymentDocuments.IdPaymentType, dbo.PaymentDocuments.DocumentNumber, 
                      dbo.PaymentDocuments.Note AS DocumentNote, dbo.PaymentTypes.Name AS PaymentType, dbo.PaymentTypes.PrintText, 
                      dbo.CustomerVehiclesRelations.IdCustomer, dbo.CustomerVehiclesRelations.IdVehicle, dbo.PaymentDocumentsDetails.Id AS IdDetal, 
                      dbo.PaymentDocumentsDetails.IdPriceCatalog, dbo.PaymentDocumentsDetails.Price, dbo.PaymentDocumentsDetails.DDV, 
                      dbo.PaymentDocumentsDetails.Note, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IsCompany, 
                      dbo.Customers.IdLivingAddress, dbo.Streets.StreetName, dbo.Cities.CityName, dbo.Cities.CityZip, dbo.Customers.LivingAddressNumber, 
                      dbo.Vehicles.ShellNumber, dbo.VehicleModel.ModelName, dbo.VehicleMakers.CompanyName, dbo.VehicleMakers.CompanyTrademark, 
                      dbo.PaymentDocumentsDetails.Discount, dbo.PaymentDocuments.Storno, dbo.PaymentDocuments.IdOperator, dbo.Communities.CommunityName, 
                      dbo.VehicleCategories.CategoryCode, dbo.VehicleCategories.CategoryName, dbo.VehicleCategoryForPayments.Code AS CategoryForPaymentsCode, 
                      dbo.VehicleCategoryForPayments.Name AS CategoryForPaymentsName, dbo.PaymentDocuments.Payed
FROM         dbo.VehicleCategories INNER JOIN
                      dbo.VehicleModel INNER JOIN
                      dbo.Vehicles ON dbo.VehicleModel.Id = dbo.Vehicles.IdVehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id ON 
                      dbo.VehicleCategories.Id = dbo.Vehicles.IdVehicleCategories INNER JOIN
                      dbo.VehicleCategoryForPayments ON dbo.Vehicles.IdVehicleCategoryForPayments = dbo.VehicleCategoryForPayments.Id RIGHT OUTER JOIN
                      dbo.PaymentItems INNER JOIN
                      dbo.PaymentItemParametars INNER JOIN
                      dbo.PaymentDocuments INNER JOIN
                      dbo.PaymentDocumentsDetails ON dbo.PaymentDocuments.Id = dbo.PaymentDocumentsDetails.IdPaymentDocuments INNER JOIN
                      dbo.PaymentTypes ON dbo.PaymentDocuments.IdPaymentType = dbo.PaymentTypes.Id INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.PaymentDocuments.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id ON 
                      dbo.PaymentItemParametars.Id = dbo.PaymentDocumentsDetails.IdPriceCatalog ON 
                      dbo.PaymentItems.Id = dbo.PaymentItemParametars.IdPaymentItem INNER JOIN
                      dbo.PaymentCategories ON dbo.PaymentItems.IdPymentCategory = dbo.PaymentCategories.Id ON 
                      dbo.Vehicles.Id = dbo.CustomerVehiclesRelations.IdVehicle LEFT OUTER JOIN
                      dbo.Communities INNER JOIN
                      dbo.Cities ON dbo.Communities.Id = dbo.Cities.IdCommunityCode ON dbo.Customers.IdLivingCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id
WHERE
	(dbo.PaymentDocumentsDetails.PrePayed = 0) AND 
	(dbo.PaymentDocumentsDetails.Active = 1) AND 
	(dbo.PaymentDocuments.Active = 1) AND
	(dbo.PaymentDocuments.Id = @idDocument)
and dbo.PaymentItemParametars.active=1


order by dbo.PaymentCategories.VisibleOrder
GO
