-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[GetPaymentDocumentForFiscalPrintByIdDocument]
	@idDocument bigint
AS
SELECT     dbo.PaymentDocuments.Id AS IdPaymentDocument, dbo.PaymentDocuments.DatePay, dbo.PaymentDocuments.IdPaymentType, 
                      dbo.PaymentTypes.Name AS PaymentType, dbo.PaymentDocumentsDetails.Id AS IdDocumentDetal, dbo.PaymentDocumentsDetails.IdPriceCatalog, 
                      dbo.PaymentItemParametars.PrametarName, dbo.PaymentDocumentsDetails.Price, dbo.PaymentDocumentsDetails.DDV, 
                      dbo.PaymentDocumentsDetails.Discount, dbo.PaymentDocuments.Storno, dbo.PaymentCategories.CategoryName As CategoryName
FROM         dbo.PaymentDocuments INNER JOIN
                      dbo.PaymentDocumentsDetails ON dbo.PaymentDocuments.Id = dbo.PaymentDocumentsDetails.IdPaymentDocuments INNER JOIN
                      dbo.PaymentItemParametars ON dbo.PaymentDocumentsDetails.IdPriceCatalog = dbo.PaymentItemParametars.Id INNER JOIN
                      dbo.PaymentTypes ON dbo.PaymentDocuments.IdPaymentType = dbo.PaymentTypes.Id INNER JOIN
                      dbo.PaymentItems ON dbo.PaymentItemParametars.IdPaymentItem = dbo.PaymentItems.Id INNER JOIN
                      dbo.PaymentCategories ON dbo.PaymentItems.IdPymentCategory = dbo.PaymentCategories.Id
WHERE
	(dbo.[PaymentDocuments].Active=1) AND
	(dbo.[PaymentDocumentsDetails].Active=1) AND
	(dbo.[PaymentDocuments].Id=@idDocument) and
	(dbo.[PaymentDocumentsDetails].PrePayed =0)
GO
