-- =============================================
-- Author:  Ivan
-- Create date: 
-- Description: 
-- =============================================
CREATE PROCEDURE [dbo].[printShortPivotPaymentDocumentByDate]
 @StartDate datetime,
 @EndDate datetime
AS
SELECT     dbo.PaymentDocuments.Id, 
  dbo.PaymentDocuments.IdOperator, 
  dbo.PaymentDocuments.DocumentNumber, 
  dbo.PaymentDocuments.DatePay, 
        dbo.PaymentDocuments.Payed, 
        dbo.PaymentDocuments.Storno, 
        dbo.PaymentDocuments.Note AS PayDocNote, 
        dbo.PaymentTypes.Name, 
        dbo.PaymentTypes.Rati, 
        dbo.PaymentDocumentsRata.Price as RataPrice, 
        dbo.PaymentDocumentsRata.Payed AS RataPayed, 
        dbo.PaymentDocumentsRata.DatePayed as RataDatePayed
FROM         dbo.PaymentDocuments INNER JOIN
                      dbo.PaymentDocumentsRata ON dbo.PaymentDocuments.Id = dbo.PaymentDocumentsRata.IdPaymentDocument INNER JOIN
                      dbo.PaymentTypes ON dbo.PaymentDocuments.IdPaymentType = dbo.PaymentTypes.Id

where  dbo.PaymentDocuments.Active = 1 AND
   ( (dbo.PaymentDocumentsRata.DatePayed >= @StartDate AND dbo.PaymentDocumentsRata.DatePayed < @EndDate))
     and not(CAST ( dbo.PaymentDocuments.Note as varchar(21)) = ('Автоматски генерирана'))
   and Not(CAST ( dbo.PaymentDocuments.Note as varchar(20)) = ('Сторнирана во сметка'))
GO
