/****** Object:  StoredProcedure [dbo].[PrintDocumentsTehnicalExamsReports]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za zimanje site zapisi

CREATE PROC [dbo].[PrintDocumentsTehnicalExamsReports]
@id bigint
AS
SELECT     dbo.DocumentsTehnicalExamsReports.Id, dbo.DocumentsTehnicalExamsReports.MadeDate, dbo.DocumentsTehnicalExamsReports.ValidTillDate, 
                      dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam, dbo.TehnicalExamOrganizations.OrganizationName, 
                      dbo.TehnicalExamOrganizations.Station, dbo.DocumentsTehnicalExamsReports.IdFirsControler, 
                      dbo.DocumentsTehnicalExamsReports.IdSecondControler, dbo.DocumentsTehnicalExamsReports.VehicleIsRight, dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName, dbo.Customers.IdLivingAddress, dbo.Customers.LivingAddressNumber, dbo.Customers.IdLivingCity, 
                      dbo.Streets.StreetName, dbo.Cities.CityName, dbo.Cities.CityZip, dbo.Countries.CountryName, dbo.Communities.CommunityName, 
                      dbo.VehicleModel.ModelName, dbo.Vehicles.MakeDate, dbo.Vehicles.NumberOfAxis, dbo.Vehicles.EngineNumber, 
                      dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, 
                      dbo.VehicleMakers.IdCountry AS IdCountryOfProduction, dbo.VehicleMakers.CompanyName, dbo.VehicleMakers.CompanyTrademark, 
                      dbo.Vehicles.PropulsionAxis, dbo.Vehicles.ShellNumber, dbo.Vehicles.EnginePower, dbo.Vehicles.NumberOfSeats, 
                      dbo.DocumentsTehnicalExamsReports.ExplanationNote, dbo.DocumentsTehnicalExamsReports.DriversWarning, dbo.Vehicles.IsSocialNotPrivate, 
                      dbo.Vehicles.ForPrivateTransportNotPublic, dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam, 
                      dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation, dbo.Vehicles.Id AS IdVehicle, dbo.Vehicles.EnginePowerOutPut, 
                      dbo.Colors.ColorCode, dbo.Colors.ColorDescription, Colors_1.ColorCode AS ColorCode2, Colors_1.ColorDescription AS ColorDescription2, 
                      dbo.VehicleEngineTypes.EngineTypeCode
FROM         dbo.Colors RIGHT OUTER JOIN
                      dbo.VehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id RIGHT OUTER JOIN
                      dbo.Vehicles INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Vehicles.Id = dbo.CustomerVehiclesRelations.IdVehicle INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id LEFT OUTER JOIN
                      dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id ON dbo.VehicleModel.Id = dbo.Vehicles.IdVehicleModel ON 
                      dbo.Colors.Id = dbo.Vehicles.IdPrimaryColor LEFT OUTER JOIN
                      dbo.Countries INNER JOIN
                      dbo.Cities ON dbo.Countries.Id = dbo.Cities.IdCountry INNER JOIN
                      dbo.Communities ON dbo.Cities.IdCommunityCode = dbo.Communities.Id INNER JOIN
                      dbo.Colors AS Colors_1 ON dbo.Countries.Id = Colors_1.Id ON dbo.Vehicles.IdSecondaryColor = Colors_1.Id AND 
                      dbo.Customers.IdLivingCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id RIGHT OUTER JOIN
                      dbo.DocumentsTehnicalExamsReports INNER JOIN
                      dbo.TehnicalExamOrganizations ON dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam = dbo.TehnicalExamOrganizations.Id ON 
                      dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation
      WHERE ( dbo.DocumentsTehnicalExamsReports.Id = @id) AND ( dbo.DocumentsTehnicalExamsReports.Active = 1)
GO
