CREATE PROC [dbo].[PrintVehicleByIdWhiteRequest] 
	@id bigint
as
SELECT     dbo.Documents.Id, dbo.CustomerVehiclesRelations.IdVehicle, dbo.VehicleModel.ModelName, dbo.Vehicles.MakeDate, 
                      dbo.VehicleMakers.CompanyName, dbo.VehicleMakers.CompanyTrademark, dbo.VehicleCategories.OldCategoryName, 
                      dbo.VehicleCategories.CategoryCode, dbo.VehicleCategories.CategoryName, dbo.VehicleCategories.MKSJUS, dbo.VehicleCategories.ISO, 
                      dbo.VehicleCategories.MKSJUSDescription, dbo.VehicleMakers.IdCountry, dbo.VehicleEngineTypes.EngineTypeCode, 
                      dbo.Vehicles.ShellNumber, dbo.Vehicles.EngineNumber, dbo.Vehicles.EnginePower, 
                      dbo.Vehicles.EnginePowerOutPut, dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, 
                      dbo.Vehicles.IdEnginePowerSource, dbo.Vehicles.IdEngineSecondPowerSource, dbo.VehicleUse.UseDescription
FROM         dbo.Vehicles INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Vehicles.Id = dbo.CustomerVehiclesRelations.IdVehicle INNER JOIN
                      dbo.VehicleUse ON dbo.Vehicles.IdVehicleUse = dbo.VehicleUse.Id INNER JOIN
                      dbo.VehicleCategories ON dbo.Vehicles.IdVehicleCategories = dbo.VehicleCategories.Id INNER JOIN
                      dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id INNER JOIN
                      dbo.VehicleModel ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id INNER JOIN
                      dbo.Documents ON dbo.CustomerVehiclesRelations.Id = dbo.Documents.IdCustomerVehicleRelation
WHERE ( dbo.Documents.Id = @id) AND ( dbo.Documents.Active = 1)
