-- Description: Procedura za zimanje na red po Primaren kluc
 
CREATE PROC [dbo].[PrintTrafficLicenceByIdVehicle] 
	@id bigint
as
SELECT     dbo.Vehicles.Id, dbo.Vehicles.IdVehicleBodyType, dbo.Vehicles.IdVehicleCategories, dbo.Vehicles.IdEngineType, dbo.Vehicles.IdEnginePowerSource, 
                      dbo.Vehicles.IdEngineSecondPowerSource, dbo.Vehicles.IdGearBox, dbo.Vehicles.IdBreakes, dbo.Vehicles.IdSupporting, dbo.Vehicles.IdVehicleModel, 
                      dbo.Vehicles.EngineNumber, dbo.Vehicles.EnginePower, dbo.Vehicles.EngineTorque, dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.ShellNumber,
                       dbo.Vehicles.MakeDate, dbo.Vehicles.NumberOfDoors, dbo.Vehicles.NumberOfSeats, dbo.Vehicles.NumberOfStandingSeats, 
                      dbo.Vehicles.NumberOfLieingSeats, dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, dbo.Vehicles.TrailerWaightWithBreak, 
                      dbo.Vehicles.TrailerWaightWithoutBreak, dbo.Vehicles.NumberOfAxis, dbo.Vehicles.PropulsionAxis, dbo.Vehicles.NumberOfWheels, 
                      dbo.Vehicles.NumberOfPropulsionWheels, dbo.Vehicles.VehicleSizeHight, dbo.Vehicles.VehicleSizeWidth, dbo.Vehicles.VehicleSizeLength, 
                      dbo.Vehicles.Suffocation, dbo.Vehicles.Hook, dbo.Vehicles.Vitlo, dbo.Vehicles.IdPrimaryColor, dbo.Vehicles.IdSecondaryColor, 
                      dbo.Vehicles.CapacityFuelTank, dbo.Vehicles.Note, dbo.Vehicles.LastChanged, dbo.VehicleModel.ModelName, dbo.VehicleMakers.CompanyName, 
                      dbo.VehicleMakers.CompanyTrademark, dbo.Countries.CountryName, dbo.VehicleEnginePowerSourceTypes.PowerSourceName AS FirstPowerSource, 
                      dbo.VehicleCategories.CategoryCode, dbo.VehicleCategories.CategoryName, dbo.VehicleBodytype.BodytypeCode, 
                      dbo.VehicleBodytype.BodytypeDescriprion, dbo.DocumentsTrafficLicences.TrafficLicenceNumber, dbo.DocumentsTrafficLicences.MadeDate, 
                      dbo.DocumentsTrafficLicences.EndDate, dbo.DocumentsTrafficLicences.Note AS TrafficLicencesNote, dbo.Customers.MB, 
                      dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IdLivingAddress, dbo.Customers.LivingAddressNumber, 
                      dbo.Customers.IdLivingCity, dbo.Customers.IdBirhCity, dbo.Customers.IdBirthAddress, dbo.Customers.BrithAddressNumber, 
                      dbo.Customers.IdCitizenship, dbo.Customers.IsCompany, dbo.Customers.Occupation, dbo.Customers.WorksInCompany, 
                      dbo.Customers.IdBusinessType, dbo.Vehicles.EnginePowerOutPut, dbo.VehicleCategories.OldCategoryName, 
                      dbo.VehicleBodytype.OldBodytypeDescription, dbo.VehicleUse.UseDescription
FROM         dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.DocumentsTrafficLicences ON dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation RIGHT OUTER JOIN
                      dbo.VehicleCategories RIGHT OUTER JOIN
                      dbo.Vehicles ON dbo.VehicleCategories.Id = dbo.Vehicles.IdVehicleCategories ON 
                      dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id LEFT OUTER JOIN
                      dbo.VehicleEngineTypes ON dbo.Vehicles.IdEngineType = dbo.VehicleEngineTypes.Id LEFT OUTER JOIN
                      dbo.VehicleUse ON dbo.Vehicles.IdVehicleUse = dbo.VehicleUse.Id LEFT OUTER JOIN
                      dbo.VehicleEnginePowerSourceTypes ON dbo.Vehicles.IdEnginePowerSource = dbo.VehicleEnginePowerSourceTypes.Id LEFT OUTER JOIN
                      dbo.Countries INNER JOIN
                      dbo.VehicleMakers INNER JOIN
                      dbo.VehicleModel ON dbo.VehicleMakers.Id = dbo.VehicleModel.IdVehicleMaker ON dbo.Countries.Id = dbo.VehicleMakers.IdCountry ON 
                      dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id LEFT OUTER JOIN
                      dbo.VehicleBodytype ON dbo.Vehicles.IdVehicleBodyType = dbo.VehicleBodytype.Id
WHERE ( dbo.DocumentsTrafficLicences.Id = @id) AND ( dbo.Vehicles.Active = 1) and DocumentsTrafficLicences.EndDate>getdate()
GO
