CREATE PROC [dbo].[printDocumentPermisionById]
	@id as bigint
AS
SELECT     dbo.DocumentsPermisions.Id, dbo.DocumentsPermisions.IdCustomerVehicleRelation, dbo.Customers.MB AS CustomerMB, 
                      dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner, 
                      dbo.CustomerVehiclesRelations.IdCustomer, Customers_1.MB AS OwnerMB, Customers_1.CustomerSurname AS OwnerSurname, 
                      Customers_1.CustomerFirstName AS OwnerFirstName, dbo.CustomerVehiclesRelations.IdVehicle, dbo.Vehicles.EngineNumber, 
                      dbo.Vehicles.ShellNumber, dbo.Vehicles.IdVehicleModel, dbo.VehicleModel.ModelName, dbo.VehicleMakers.CompanyName, 
                      dbo.DocumentsPermisions.TrafficLicenceNumber, dbo.DocumentsPermisions.TriptiqueNumber, dbo.DocumentsPermisions.DateCreated, 
                      dbo.DocumentsPermisions.ValidTillDate, dbo.DocumentsPermisions.Note, dbo.Customers.PassportNumber AS CustomerPasswordNumber, 
                      Customers_1.LivingAddressNumber AS OwnerLivingAddressNumber, Customers_1.IdLivingAddress AS IdOwnerLivingAdress, 
                      dbo.Streets.StreetName AS OwnerStreet, Customers_1.IdLivingCity AS IdOwnerLivingCity, dbo.Cities.CityName AS OwnerLivingCity, 
                      Customers_1.BLK AS OwnerBLK, dbo.DocumentsPermisions.IdIssuer, dbo.RegistrationIssuers.IssuerName, 
                      dbo.DocumentsPermisions.IdCityOfIssuing, Cities_1.CityName AS CityOfIssuing
FROM         dbo.Vehicles INNER JOIN
                      dbo.VehicleMakers INNER JOIN
                      dbo.VehicleModel ON dbo.VehicleMakers.Id = dbo.VehicleModel.IdVehicleMaker ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Vehicles.Id = dbo.CustomerVehiclesRelations.IdVehicle INNER JOIN
                      dbo.Streets INNER JOIN
                      dbo.Customers AS Customers_1 ON dbo.Streets.Id = Customers_1.IdLivingAddress INNER JOIN
                      dbo.Cities ON Customers_1.IdLivingCity = dbo.Cities.Id ON dbo.CustomerVehiclesRelations.IdCustomer = Customers_1.Id RIGHT OUTER JOIN
                      dbo.RegistrationIssuers INNER JOIN
                      dbo.DocumentsPermisions ON dbo.RegistrationIssuers.Id = dbo.DocumentsPermisions.IdIssuer INNER JOIN
                      dbo.Cities AS Cities_1 ON dbo.DocumentsPermisions.IdCityOfIssuing = Cities_1.Id LEFT OUTER JOIN
                      dbo.Customers INNER JOIN
                      dbo.CustomerVehiclesRelations AS CustomerVehiclesRelations_1 ON dbo.Customers.Id = CustomerVehiclesRelations_1.IdCustomer ON 
                      dbo.DocumentsPermisions.IdCustomerVehicleRelation = CustomerVehiclesRelations_1.Id ON 
                      dbo.CustomerVehiclesRelations.Id = dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner
WHERE
	(dbo.DocumentsPermisions.Id = @id)
GO
