                      dbo.DocumentsTehnicalExamsReports.ValidTillDate, dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam, 
                      dbo.DocumentsTehnicalExamsReports.IdFirsControler, dbo.DocumentsTehnicalExamsReports.IdSecondControler, 
                      dbo.DocumentsTehnicalExamsReports.VehicleIsRight, dbo.DocumentsTehnicalExamsReports.ExplanationNote, 
                      dbo.DocumentsTehnicalExamsReports.DriversWarning, dbo.DocumentsTehnicalExamsReports.LastChanged, dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName, dbo.Customers.IsCompany, dbo.Vehicles.ShellNumber, dbo.Vehicles.EngineNumber, 
                      dbo.Vehicles.IsSocialNotPrivate, dbo.Vehicles.ForPrivateTransportNotPublic, dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam, 
                      dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation, dbo.Vehicles.Id AS IdVehicle, 
                      dbo.TehnicalExamsTypes.Description AS TehnicalExamType, dbo.Vehicles.IdVehicleModel, dbo.VehicleModel.ModelName as VehicleModel, 
                      dbo.VehicleMakers.CompanyName as VahiceMaker, dbo.DocumentsTehnicalExamsReports.Note
FROM         dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.VehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id ON 
                      dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id RIGHT OUTER JOIN
                      dbo.TehnicalExamsTypes INNER JOIN
                      dbo.DocumentsTehnicalExamsReports ON dbo.TehnicalExamsTypes.Id = dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam ON 
                      dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation
WHERE     (dbo.DocumentsTehnicalExamsReports.Active = 1)
ORDER BY dbo.DocumentsTehnicalExamsReports.Id DESC
GO
/****** Object:  StoredProcedure [dbo].[getDocumentsTehnicalExamsReportsListBetweenDates]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za zimanje site zapisi

CREATE PROC [dbo].[getDocumentsTehnicalExamsReportsListBetweenDates]
@od datetime,
@do datetime
AS
 SELECT     dbo.DocumentsTehnicalExamsReports.Id, 
dbo.DocumentsTehnicalExamsReports.RegNumber, 
dbo.DocumentsTehnicalExamsReports.MadeDate, 
                      dbo.DocumentsTehnicalExamsReports.ValidTillDate, 
dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam, 
                      dbo.DocumentsTehnicalExamsReports.IdFirsControler, 
dbo.DocumentsTehnicalExamsReports.IdSecondControler, 
                      dbo.DocumentsTehnicalExamsReports.VehicleIsRight, 
dbo.DocumentsTehnicalExamsReports.ExplanationNote, 
                      dbo.DocumentsTehnicalExamsReports.DriversWarning, 
dbo.DocumentsTehnicalExamsReports.LastChanged, 
dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName, 
dbo.Customers.IsCompany, 
dbo.Vehicles.ShellNumber, 
dbo.Vehicles.EngineNumber, 
                      dbo.Vehicles.IsSocialNotPrivate, 
dbo.Vehicles.ForPrivateTransportNotPublic, 
dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam, 
                      dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation, 
dbo.Vehicles.Id AS IdVehicle, 
                      dbo.TehnicalExamsTypes.Description AS TehnicalExamType, 
dbo.Vehicles.IdVehicleModel, dbo.VehicleModel.ModelName as VehicleModel, 
                      dbo.VehicleMakers.CompanyName as VahiceMaker, dbo.DocumentsTehnicalExamsReports.Note
FROM         dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.VehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id ON 
                      dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id RIGHT OUTER JOIN
                      dbo.TehnicalExamsTypes INNER JOIN
                      dbo.DocumentsTehnicalExamsReports ON dbo.TehnicalExamsTypes.Id = dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam ON 
                      dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation
 WHERE dbo.DocumentsTehnicalExamsReports.Active = 1 and 
(dbo.DocumentsTehnicalExamsReports.ValidTillDate>=DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()))) and
(dbo.DocumentsTehnicalExamsReports.MadeDate between @od and @do)
GO
