                      dbo.Documents.IdOperatorModified, dbo.Documents.IdOperatorEnded, dbo.Documents.IdTechnicalExamReport, dbo.Documents.DateCreated, 
                      dbo.Documents.DateModified, dbo.Documents.DateEnded, dbo.Documents.VehicleOwnershipProof, dbo.Documents.IdPayAttachment, 
                      dbo.Documents.Note, dbo.CustomerVehiclesRelations.IdCustomer, dbo.CustomerVehiclesRelations.IdVehicle, 
                      dbo.DocumentTypes.DocumentTypeName, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IsCompany, 
                      dbo.Vehicles.ShellNumber, dbo.Vehicles.EngineNumber, dbo.DocumentsTehnicalExamsReports.VehicleIsRight, dbo.VehicleModel.ModelName, 
                      dbo.VehicleMakers.CompanyName
FROM         dbo.Documents INNER JOIN
