                      dbo.Requests.IdOperatorModified, dbo.Requests.IdOperatorEnded, dbo.Requests.IdTechnicalExamReport, dbo.Requests.DateCreated, 
                      dbo.Requests.DateModified, dbo.Requests.DateEnded, dbo.RequestTypes.IdDocumentPrint, dbo.Requests.IdRequestType
FROM         dbo.Requests INNER JOIN
                      dbo.RequestTypes ON dbo.Requests.IdRequestType = dbo.RequestTypes.Id INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Requests.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.VehicleMakers INNER JOIN
