                      dbo.Vehicles ON dbo.VehicleModel.Id = dbo.Vehicles.IdVehicleModel ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id INNER JOIN
                      dbo.DocumentTypePrint ON dbo.RequestTypes.IdDocumentPrint = dbo.DocumentTypePrint.Id
WHERE (dbo.Requests.Active=1) AND (dbo.Requests.DateEnded is null)
