	dbo.Customers.MB AS CustomerMB, 
	dbo.Customers.CustomerSurname,
	dbo.Customers.CustomerFirstName,
	dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner, 
	dbo.CustomerVehiclesRelations.IdCustomer,
	Customers_1.MB AS OwnerMB,
	Customers_1.CustomerSurname AS OwnerSurname, 
	Customers_1.CustomerFirstName AS OwnerFirstName,
	dbo.CustomerVehiclesRelations.IdVehicle,
	dbo.Vehicles.EngineNumber, 
	dbo.Vehicles.ShellNumber,
	dbo.Vehicles.IdVehicleModel,
	dbo.VehicleModel.ModelName,
	dbo.VehicleMakers.CompanyName, 
	dbo.DocumentsPermisions.TrafficLicenceNumber,
	dbo.DocumentsPermisions.TriptiqueNumber,
	dbo.DocumentsPermisions.DateCreated, 
	dbo.DocumentsPermisions.ValidTillDate,
	dbo.DocumentsPermisions.Note
FROM         dbo.Customers INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Customers.Id = dbo.CustomerVehiclesRelations.IdCustomer INNER JOIN
                      dbo.DocumentsPermisions INNER JOIN
                      dbo.CustomerVehiclesRelations AS CustomerVehiclesRelations_1 ON 
                      dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner = CustomerVehiclesRelations_1.Id INNER JOIN
                      dbo.Customers AS Customers_1 ON CustomerVehiclesRelations_1.IdCustomer = Customers_1.Id INNER JOIN
                      dbo.Vehicles ON CustomerVehiclesRelations_1.IdVehicle = dbo.Vehicles.Id INNER JOIN
                      dbo.VehicleMakers INNER JOIN
                      dbo.VehicleModel ON dbo.VehicleMakers.Id = dbo.VehicleModel.IdVehicleMaker ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id ON 
                      dbo.CustomerVehiclesRelations.Id = dbo.DocumentsPermisions.IdCustomerVehicleRelation
WHERE
	(dbo.DocumentsPermisions.Active = 1)
GO
