                      dbo.Vehicles.IdEngineSecondPowerSource, dbo.Vehicles.IdGearBox, dbo.Vehicles.IdBreakes, dbo.Vehicles.IdSupporting, dbo.Vehicles.IdVehicleModel, 
                      dbo.Vehicles.IdPrimaryColor, dbo.Vehicles.IdSecondaryColor,
					  dbo.Vehicles.IdVehicleCategoryForPayments,
					  dbo.Vehicles.EngineNumber, dbo.Vehicles.EnginePower, dbo.Vehicles.EngineTorque, 
                      dbo.Vehicles.EngineWorkingCapacity, dbo.Vehicles.EnginePowerOutPut, dbo.Vehicles.ShellNumber, dbo.Vehicles.MakeDate, 
                      dbo.Vehicles.NumberOfDoors, dbo.Vehicles.NumberOfSeats, dbo.Vehicles.NumberOfStandingSeats, dbo.Vehicles.NumberOfLieingSeats, 
                      dbo.Vehicles.EmptyWaight, dbo.Vehicles.MaximunAllowedWaight, dbo.Vehicles.TrailerWaightWithBreak, dbo.Vehicles.TrailerWaightWithoutBreak, 
                      dbo.Vehicles.NumberOfAxis, dbo.Vehicles.PropulsionAxis, dbo.Vehicles.NumberOfWheels, dbo.Vehicles.NumberOfPropulsionWheels, 
                      dbo.Vehicles.VehicleSizeHight, dbo.Vehicles.VehicleSizeWidth, dbo.Vehicles.VehicleSizeLength, dbo.Vehicles.Suffocation, dbo.Vehicles.Hook, 
                      dbo.Vehicles.Vitlo, dbo.Vehicles.HologationSertificateNumber, dbo.Vehicles.NoiseStatic, dbo.Vehicles.NoiseMovment, dbo.Vehicles.CO, 
                      dbo.Vehicles.HC, dbo.Vehicles.NOx, dbo.Vehicles.HCNOx, dbo.Vehicles.Blackening, dbo.Vehicles.Pinpoints, dbo.Vehicles.CO2, 
                      dbo.Vehicles.FuelConsumption, dbo.Vehicles.CapacityFuelTank, dbo.Vehicles.Note, dbo.Vehicles.IsSocialNotPrivate, 
