CREATE PROC [dbo].[getVehiclesListWithOwners]
AS
      SELECT     dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.MB, dbo.Vehicles.EngineNumber, dbo.Vehicles.ShellNumber, 
                       dbo.VehicleModel.ModelName, dbo.VehicleMakers.CompanyName, 
                      dbo.VehicleMakers.CompanyTrademark, dbo.Vehicles.Id,
						dbo.CustomerVehiclesRelations.Id as RelationId
FROM         dbo.VehicleModel INNER JOIN
                      dbo.Vehicles ON dbo.VehicleModel.Id = dbo.Vehicles.IdVehicleModel INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id RIGHT OUTER JOIN
                      dbo.CustomerVehiclesRelations INNER JOIN
