 WHERE dbo.CustomerVehiclesRelations.Active = 1 and
dbo.CustomerVehiclesRelationTypes.IsOwner = 1 and (dbo.CustomerVehiclesRelations.EndDate is null or dbo.CustomerVehiclesRelations.EndDate>getdate())
ORDER BY dbo.Vehicles.Id DESC
