CREATE PROCEDURE [dbo].[depListOfIncorectTehnicalExams] 
	@idOrganization int,
	@date datetime
AS
SELECT     dbo.DocumentsTehnicalExamsReports.Id AS IdTehnicalExam,
		   dbo.DocumentsTehnicalExamsReports.MadeDate, 
           dbo.DocumentsTehnicalExamsReports.ValidTillDate, 
           dbo.DocumentsTehnicalExamsReports.IdFirsControler, 
           dbo.DocumentsTehnicalExamsReports.IdSecondControler, 
           dbo.DocumentsTehnicalExamsReports.ExplanationNote, 
           dbo.DocumentsTehnicalExamsReports.DriversWarning, 
           dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation, 
           dbo.CustomerVehiclesRelations.IdCustomer, 
           dbo.CustomerVehiclesRelations.IdVehicle, 
           dbo.Customers.CustomerSurname, 
           dbo.Customers.CustomerFirstName, 
           dbo.Vehicles.ShellNumber, 
           dbo.Vehicles.EngineNumber, 
           dbo.VehicleModel.ModelName AS VehicleModel, 
           dbo.VehicleMakers.CompanyName AS VehicleMaker, 
           dbo.TehnicalExamsTypes.Description
FROM       dbo.DocumentsTehnicalExamsReports INNER JOIN
           dbo.CustomerVehiclesRelations 
           ON dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation INNER JOIN
           dbo.Customers 
           ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
           dbo.Vehicles 
           ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id INNER JOIN
           dbo.VehicleModel 
           ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id INNER JOIN
           dbo.VehicleMakers 
           ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id INNER JOIN
           dbo.TehnicalExamsTypes 
           ON dbo.DocumentsTehnicalExamsReports.IdTypeOfTehnicalExam = dbo.TehnicalExamsTypes.Id
WHERE
	([dbo].[DocumentsTehnicalExamsReports].IdOrganizationForTehnicalExam=@idOrganization) AND
	([dbo].[DocumentsTehnicalExamsReports].Active = 1) AND
	(([dbo].[DocumentsTehnicalExamsReports].VehicleIsRight=0) OR
	([dbo].[DocumentsTehnicalExamsReports].IdSecondControler=0)) AND
	([dbo].[DocumentsTehnicalExamsReports].ValidTillDate > @date)
GO
