CREATE PROCEDURE [dbo].[depCustomerFinansicalState] 

AS
SELECT     dbo.CustomerFinancialState.Id, dbo.CustomerFinancialState.IdCustomerVehicleRelation, dbo.CustomerFinancialState.IdDocument, 
                      dbo.CustomerFinancialState.IdDocumentTehnicalExam, dbo.CustomerFinancialState.IdDocumentsTrafficLicences, 
                      dbo.CustomerFinancialState.IdDocumentIternationalDriveingLicence, dbo.CustomerFinancialState.IdDocumentPermisions, 
                      dbo.CustomerFinancialState.IdPriceCatalog, dbo.CustomerFinancialState.Note, dbo.CustomerFinancialState.Price, dbo.CustomerFinancialState.Payed, 
                      dbo.CustomerVehiclesRelations.IdVehicle, dbo.CustomerVehiclesRelations.IdCustomer, dbo.Vehicles.ShellNumber, 
                      dbo.VehicleModel.ModelName AS VehicleModel, dbo.VehicleMakers.CompanyName AS VehicleMaker, dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName
FROM         dbo.CustomerFinancialState INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.CustomerFinancialState.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.Vehicles INNER JOIN
                      dbo.VehicleModel ON dbo.Vehicles.IdVehicleModel = dbo.VehicleModel.Id INNER JOIN
                      dbo.VehicleMakers ON dbo.VehicleModel.IdVehicleMaker = dbo.VehicleMakers.Id ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id
WHERE     ( [dbo].CustomerFinancialState.Active = 1) and ( [dbo].CustomerFinancialState.Payed =0)
GO
/****** Object:  StoredProcedure [dbo].[updatePaymentCategorie]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za UPDATE na zapis

CREATE  PROC [dbo].[updatePaymentCategorie]
		@Id int,
		@IdDDV int,
		@IdCalculationItem int,
		@CategoryName nvarchar(250),
		@AllowDiscount bit,
		@TrigerdByRequest bit,
		@TrigerdByTechnicalExam bit,
		@TrigerdByTrafficLicence bit,
		@TrigerdByPremisionForVehicle bit,
		@TrigerdByInternationalDrivierLicence bit,
		@TrigerdByIrregularTechnicalExam bit,
		@VisibleOrder int,
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [PaymentCategories]
		SET
		IdDDV = @idddv,
		IdCalculationItem = @idcalculationitem,
		CategoryName = @categoryname,
		AllowDiscount = @allowdiscount,
		TrigerdByRequest = @trigerdbyrequest,
		TrigerdByTechnicalExam = @trigerdbytechnicalexam,
		TrigerdByTrafficLicence = @trigerdbytrafficlicence,
		TrigerdByPremisionForVehicle = @trigerdbypremisionforvehicle,
		TrigerdByInternationalDrivierLicence = @trigerdbyinternationaldrivierlicence,
		TrigerdByIrregularTechnicalExam = @trigerdbyirregulartechnicalexam,
		VisibleOrder = @visibleorder
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [PaymentCategories] WHERE ID=@id
	RETURN
GO
