/****** Object:  StoredProcedure [dbo].[addPaymentCategorie]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za dodavanje na nov zapis

CREATE  PROC [dbo].[addPaymentCategorie]
		@IdDDV int,
		@IdCalculationItem int,
		@CategoryName nvarchar(250),
		@AllowDiscount bit,
		@TrigerdByRequest bit,
		@TrigerdByTechnicalExam bit,
		@TrigerdByTrafficLicence bit,
		@TrigerdByPremisionForVehicle bit,
		@TrigerdByInternationalDrivierLicence bit,
		@TrigerdByIrregularTechnicalExam bit,
		@VisibleOrder int,
		@NewId int output,
		@newLastChanged timestamp output
AS
    INSERT INTO [PaymentCategories]
		(
		IdDDV,
		IdCalculationItem,
		CategoryName,
		AllowDiscount,
		TrigerdByRequest,
		TrigerdByTechnicalExam,
		TrigerdByTrafficLicence,
		TrigerdByPremisionForVehicle,
		TrigerdByInternationalDrivierLicence,
		TrigerdByIrregularTechnicalExam,
		VisibleOrder
		)
		VALUES
		(
		@IdDDV,
		@IdCalculationItem,
		@CategoryName,
		@AllowDiscount,
		@TrigerdByRequest,
		@TrigerdByTechnicalExam,
		@TrigerdByTrafficLicence,
		@TrigerdByPremisionForVehicle,
		@TrigerdByInternationalDrivierLicence,
		@TrigerdByIrregularTechnicalExam,
		@VisibleOrder
		)
	
	SELECT @NewId = Id, @newLastChanged = LastChanged
	FROM [PaymentCategories] WHERE Id=SCOPE_IDENTITY()
	RETURN
GO
