		)
		VALUES
		(
		@OrganizationName,
		@Station,
		@IdCity
		)
	
	SELECT @NewId = Id, @newLastChanged = LastChanged
	FROM [TehnicalExamOrganizations] WHERE Id=SCOPE_IDENTITY()
	RETURN
GO
