CREATE PROC [dbo].[updateTehnicalExamOrganization]
		@Id int,
		@OrganizationName nvarchar(150),
		@Station nvarchar(150),
		@IdCity int,
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [TehnicalExamOrganizations]
		SET
		OrganizationName = @organizationname,
		Station = @station,
		IdCity = @idcity
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [TehnicalExamOrganizations] WHERE ID=@id
	RETURN
GO
