CREATE PROC [dbo].[getLastVehicleTehnicalExam]
@idVehicle bigint
AS
SELECT     dbo.TehnicalExamOrganizations.OrganizationName, dbo.TehnicalExamOrganizations.Station, dbo.Cities.CityName, 
                      dbo.Communities.CommunityName, dbo.Countries.CountryName, dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation, 
                      dbo.DocumentsTehnicalExamsReports.MadeDate, dbo.DocumentsTehnicalExamsReports.ValidTillDate, 
                      dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam, dbo.DocumentsTehnicalExamsReports.IdFirsControler, 
                      dbo.DocumentsTehnicalExamsReports.IdSecondControler, dbo.DocumentsTehnicalExamsReports.VehicleIsRight, 
                      dbo.DocumentsTehnicalExamsReports.ExplanationNote, dbo.DocumentsTehnicalExamsReports.DriversWarning, 
                      dbo.CustomerVehiclesRelations.IdVehicle 
FROM         dbo.TehnicalExamOrganizations INNER JOIN
                      dbo.Countries INNER JOIN
                      dbo.Cities ON dbo.Countries.Id = dbo.Cities.IdCountry INNER JOIN
                      dbo.Communities ON dbo.Cities.IdCommunityCode = dbo.Communities.Id ON dbo.TehnicalExamOrganizations.IdCity = dbo.Cities.Id RIGHT OUTER JOIN
                      dbo.DocumentsTehnicalExamsReports INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.DocumentsTehnicalExamsReports.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id ON 
                      dbo.TehnicalExamOrganizations.Id = dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam
where    dbo.[CustomerVehiclesRelations].IdVehicle=@idVehicle and
		 dbo.[DocumentsTehnicalExamsReports].Active=1 and
		 dbo.[DocumentsTehnicalExamsReports].ValidTillDate>getdate()
GO
