/****** Object:  StoredProcedure [dbo].[printPlav]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[printPlav] 
	-- Add the parameters for the stored procedure here
	@id bigint
AS
SELECT     dbo.Requests.Id, 
	dbo.Requests.IdRequestType, 
	dbo.Requests.IdCustomerVehicleRelation, 
	dbo.Requests.IdCustomerVehicleRelationNew, 
    dbo.Requests.IsCustomerChanged, 
	dbo.Requests.IsVehicleChanged, 
	dbo.Requests.Note, 
	dbo.CustomerVehiclesRelations.IdCustomer, 
    dbo.CustomerVehiclesRelations.IdVehicle, 
	dbo.Requests.IdPreviousRegistration, 
    dbo.[Vehicle.Registrations].RegistrationNumber AS RegistrationNumberPrevios, 
	dbo.[Vehicle.Registrations].DateOfRegistration, 
    dbo.Requests.DateCreated, 
	dbo.Requests.DateModified, 
	dbo.Requests.DateEnded, 
	dbo.Requests.IdTechnicalExamReport, 
    dbo.DocumentsTehnicalExamsReports.MadeDate AS MadeDateTehnicalExam, 
    dbo.DocumentsTehnicalExamsReports.ValidTillDate AS ValidTillDateTehnicalExam, 
	dbo.DocumentsTehnicalExamsReports.VehicleIsRight, 
    dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam, 
	dbo.DocumentsTehnicalExamsReports.RegNumber,
	dbo.TehnicalExamOrganizations.OrganizationName, 
    dbo.TehnicalExamOrganizations.Station, 
	dbo.TehnicalExamOrganizations.IdCity, 
	dbo.Cities.CityName AS CityNameTehnicalOrganization, 
    dbo.[Vehicle.Registrations].IdRegistrationIssuer, 
	dbo.RegistrationIssuers.IssuerName, 
	dbo.[Vehicle.Registrations].DateRegistrationValidTill, 
    dbo.[Vehicle.Registrations].PlaceOfRegistration, 
	dbo.[Vehicle.Registrations].IsFirstRegistration
FROM         dbo.[Vehicle.Registrations] INNER JOIN
                      dbo.RegistrationIssuers ON dbo.[Vehicle.Registrations].IdRegistrationIssuer = dbo.RegistrationIssuers.Id RIGHT OUTER JOIN
                      dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Requests ON dbo.CustomerVehiclesRelations.Id = dbo.Requests.IdCustomerVehicleRelation ON 
                      dbo.[Vehicle.Registrations].Id = dbo.Requests.IdPreviousRegistration LEFT OUTER JOIN
                      dbo.TehnicalExamOrganizations INNER JOIN
                      dbo.Cities ON dbo.TehnicalExamOrganizations.IdCity = dbo.Cities.Id INNER JOIN
                      dbo.DocumentsTehnicalExamsReports ON 
                      dbo.TehnicalExamOrganizations.Id = dbo.DocumentsTehnicalExamsReports.IdOrganizationForTehnicalExam ON 
                      dbo.Requests.IdTechnicalExamReport = dbo.DocumentsTehnicalExamsReports.Id
WHERE  dbo.Requests.Id =@id

SELECT
	dbo.[Request.PaymentProof].Id,
	dbo.[Request.PaymentProof].IdRequest,
	dbo.[Request.PaymentProof].IdPaymentProof,
	dbo.DocumentPaymentProof.PaymentProofName as PaymentProofType,
	dbo.[Request.PaymentProof].PaymentProof as PaymentProofNumber
FROM         dbo.[Request.PaymentProof] INNER JOIN
                      dbo.DocumentPaymentProof ON dbo.[Request.PaymentProof].IdPaymentProof = dbo.DocumentPaymentProof.Id
WHERE (dbo.[Request.PaymentProof].IdRequest=@id) and (dbo.[Request.PaymentProof].Active=1)

SELECT     dbo.[Request.VehicleOwnershipProofs].Id, dbo.[Request.VehicleOwnershipProofs].IdRequest, 
                      dbo.[Request.VehicleOwnershipProofs].IdVehicleOwnershipProof, 
                      dbo.DocumentVehicleOwnershipProof.VehicleOwnershipProofName AS VehicleOwnershipProofType, 
                      dbo.[Request.VehicleOwnershipProofs].VehicleOwnershipProof AS VehicleOwnershipProofNumber
FROM         dbo.DocumentVehicleOwnershipProof INNER JOIN
                      dbo.[Request.VehicleOwnershipProofs] ON dbo.DocumentVehicleOwnershipProof.Id = dbo.[Request.VehicleOwnershipProofs].IdVehicleOwnershipProof
WHERE (dbo.[Request.VehicleOwnershipProofs].IdRequest=@id) and (dbo.[Request.VehicleOwnershipProofs].Active=1)
GO
