CREATE PROC [dbo].[PrintDocumentInternatiomalDriveingLicence]
@id bigint
AS
SELECT     dbo.DocumentsInternationalDriveingLicences.Id, dbo.DocumentsInternationalDriveingLicences.IdCustomer, dbo.Customers.MB, 
                      dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.DocumentsInternationalDriveingLicences.IdIssuer, 
                      dbo.TehnicalExamOrganizations.OrganizationName, dbo.TehnicalExamOrganizations.Station, 
                      dbo.DocumentsInternationalDriveingLicences.NumberOfLicence, dbo.DocumentsInternationalDriveingLicences.NumberOfNationalLicence, 
                      dbo.DocumentsInternationalDriveingLicences.DateCreated, dbo.DocumentsInternationalDriveingLicences.ValidTillDate, 
                      dbo.DocumentsInternationalDriveingLicences.Note, dbo.Customers.IdBirhCity, dbo.Cities.CityName AS BirthCity, dbo.Customers.DateOfBirth, 
                      dbo.TehnicalExamOrganizations.IdCity, Cities_1.CityName AS CityIssuedFrom, dbo.Customers.IdLivingCity, Cities_2.CityName AS LivingCity, 
                      dbo.Customers.PassportNumber, dbo.Customers.BrithAddressNumber, dbo.Countries.Citizenship, dbo.Customers.BLK, 
                      dbo.Customers.LivingAddressNumber, dbo.Streets.StreetName
FROM         dbo.DocumentsInternationalDriveingLicences INNER JOIN
                      dbo.Customers ON dbo.DocumentsInternationalDriveingLicences.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.TehnicalExamOrganizations ON dbo.DocumentsInternationalDriveingLicences.IdIssuer = dbo.TehnicalExamOrganizations.Id INNER JOIN
                      dbo.Cities AS Cities_1 ON dbo.TehnicalExamOrganizations.IdCity = Cities_1.Id LEFT OUTER JOIN
                      dbo.Cities ON dbo.Customers.IdBirhCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id LEFT OUTER JOIN
                      dbo.Cities AS Cities_2 ON dbo.Customers.IdLivingCity = Cities_2.Id LEFT OUTER JOIN
                      dbo.Countries ON dbo.Customers.IdCitizenship = dbo.Countries.Id
                      WHERE     (dbo.DocumentsInternationalDriveingLicences.Active = 1) and (dbo.DocumentsInternationalDriveingLicences.id=@id)
GO
