CREATE PROC [dbo].[PrintDocumentPermisionForCustomerByIdDocumentPermision]
@Id bigint
AS
SELECT     dbo.DocumentsPermisions.DateCreated, dbo.DocumentsPermisions.ValidTillDate, dbo.CustomerVehiclesRelations.IdVehicle, 
                      dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IdLivingAddress, dbo.Customers.LivingAddressNumber, 
                      dbo.Customers.PassportNumber, dbo.Customers.IdLivingCity, dbo.Cities.CityName, dbo.Streets.StreetName, 
                      dbo.DocumentsPermisions.IdCustomerVehicleRelation, dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner, 
                      dbo.CustomerVehiclesRelations.IdCustomer
FROM         dbo.Streets RIGHT OUTER JOIN
                      dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id LEFT OUTER JOIN
                      dbo.Cities ON dbo.Customers.IdLivingCity = dbo.Cities.Id ON dbo.Streets.Id = dbo.Customers.IdLivingAddress RIGHT OUTER JOIN
                      dbo.DocumentsPermisions ON dbo.CustomerVehiclesRelations.Id = dbo.DocumentsPermisions.IdCustomerVehicleRelation
where   dbo.DocumentsPermisions.active=1 and dbo.DocumentsPermisions.Id=@Id
