/****** Object:  StoredProcedure [dbo].[updateCustomerVehiclesRelationsByDocumentTypeOptionDetail]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za zimanje site zapisi

CREATE PROC [dbo].[updateCustomerVehiclesRelationsByDocumentTypeOptionDetail]
@docTypeOptionDetail int,
@IdCustomerVehicleRelation bigint,
@IdCustomerVehicleRelationHistory bigint,
@TerminationNote nvarchar(150)
AS
declare @IsVehicleDeleted bit
declare @IsNewCustomer bit
declare @IsRelationDeleted bit
set @IsVehicleDeleted = (select IsVehicleDeleted from DocumentTypesOptionsDetails where Id=@docTypeOptionDetail)
set @IsNewCustomer = (select IsNewCustomer from DocumentTypesOptionsDetails where Id=@docTypeOptionDetail)
set @IsRelationDeleted = (select IsRelationDeleted from DocumentTypesOptionsDetails where Id=@docTypeOptionDetail)

if @IsRelationDeleted=1
	begin
		update [CustomerVehiclesRelations] 
		set EndDate=getdate(),TerminationNote=@TerminationNote
		where Id=@IdCustomerVehicleRelation and Active=1
	end 

if @IsVehicleDeleted = 1
	begin
		declare @idV as bigint
		set @idV= (select IdVehicle from [CustomerVehiclesRelations] 
		where [CustomerVehiclesRelations].Id=@IdCustomerVehicleRelation)
		update [Vehicles]
		set Active=0
		where Id = @idV
	end

if @IsNewCustomer = 1
	begin
		update [CustomerVehiclesRelations] set EndDate=getdate(),TerminationNote=@TerminationNote
		where Id=@IdCustomerVehicleRelationHistory and Active=1
		update [CustomerVehiclesRelations] set StartDate=getdate()
		where Id=@IdCustomerVehicleRelation and Active=1
		
	end
GO
/****** Object:  StoredProcedure [dbo].[updateCustomerVehiclesRelationsByDocumentTypeOption]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za zimanje site zapisi

CREATE PROC [dbo].[updateCustomerVehiclesRelationsByDocumentTypeOption]
@docTypeOption int,
@IdCustomerVehicleRelation bigint,
@IdCustomerVehicleRelationHistory bigint,
@TerminationNote nvarchar(150)
AS
declare @isRelationDeleted bit
declare @isVehicleDeleted bit
set @isRelationDeleted = (select RelationDeleted from DocumentTypesOptions where Id=@docTypeOption)
set @isVehicleDeleted = (select VehicleDeleted from DocumentTypesOptions where Id=@docTypeOption)
if @isRelationDeleted = 1
begin
if @IdCustomerVehicleRelationHistory>0
	begin
		update [CustomerVehiclesRelations] set EndDate=getdate(),TerminationNote=@TerminationNote
		where Id=@IdCustomerVehicleRelationHistory and Active=1
		update [CustomerVehiclesRelations] set StartDate=getdate()
		where Id=@IdCustomerVehicleRelation and Active=1
		
		if @isVehicleDeleted = 1
		begin
			declare @idVe as bigint
			set @idVe= (select IdVehicle from [CustomerVehiclesRelations] 
			where [CustomerVehiclesRelations].Id=@IdCustomerVehicleRelationHistory)
			update [Vehicles]
			set Active=0
			where Id = @idVe
		end
	end
	
else

	begin
		update [CustomerVehiclesRelations] 
		set EndDate=getdate(),TerminationNote=@TerminationNote
		where Id=@IdCustomerVehicleRelation and Active=1
		if @isVehicleDeleted = 1
		begin
			declare @idV as bigint
			set @idV= (select IdVehicle from [CustomerVehiclesRelations] 
			where [CustomerVehiclesRelations].Id=@IdCustomerVehicleRelation)
			update [Vehicles]
			set Active=0
			where Id = @idV
		end
	end

end
GO
