CREATE PROC [dbo].[getDocumentsNotEnded]
@idCustomer bigint,
@idVehicle bigint,
@idDocType int
AS
SELECT     dbo.Documents.Id, dbo.Documents.IdDocumentType, dbo.Documents.IdCustomerVehicleRelation, dbo.Documents.IdOperatorCreated, 
                      dbo.Documents.IdOperatorModified, dbo.Documents.IdOperatorEnded, dbo.Documents.IdTechnicalExamReport, dbo.Documents.DateCreated, 
                      dbo.Documents.DateModified, dbo.Documents.DateEnded, dbo.Documents.VehicleOwnershipProof, dbo.Documents.IdPayAttachment, 
                      dbo.Documents.Note, dbo.CustomerVehiclesRelations.IdCustomer, dbo.CustomerVehiclesRelations.IdVehicle, 
                      dbo.DocumentTypes.DocumentTypeName, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IsCompany, 
                      dbo.Vehicles.ShellNumber, dbo.Vehicles.EngineNumber, dbo.DocumentsTehnicalExamsReports.VehicleIsRight
FROM         dbo.Documents INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Documents.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id INNER JOIN
                      dbo.DocumentTypes ON dbo.Documents.IdDocumentType = dbo.DocumentTypes.Id LEFT OUTER JOIN
                      dbo.DocumentsTehnicalExamsReports ON dbo.Documents.IdTechnicalExamReport = dbo.DocumentsTehnicalExamsReports.Id
where    dbo.CustomerVehiclesRelations.IdCustomer=@idCustomer and 
		 dbo.CustomerVehiclesRelations.IdVehicle=@idVehicle and
		 dbo.Documents.IdDocumentType=@idDocType and
		 dbo.Documents.IdOperatorEnded=0
GO
