CREATE PROC [dbo].[getCustomerFinancialStateByIdCustomerVehicleRelation]
@IdCustomerVehicleRelation bigint
AS
SELECT     dbo.CustomerFinancialState.Id, dbo.CustomerFinancialState.IdCustomerVehicleRelation, dbo.CustomerFinancialState.IdDocument, 
                      dbo.CustomerFinancialState.IdDocumentTehnicalExam, dbo.CustomerFinancialState.IdDocumentsTrafficLicences, 
                      dbo.CustomerFinancialState.IdDocumentIternationalDriveingLicence, dbo.CustomerFinancialState.IdDocumentPermisions, 
                      dbo.CustomerFinancialState.IdPriceCatalog, dbo.CustomerFinancialState.Note, dbo.CustomerFinancialState.Price, dbo.CustomerFinancialState.Payed, 
                      dbo.CustomerFinancialState.LastChanged, dbo.Vehicles.ShellNumber, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName
FROM         dbo.CustomerFinancialState INNER JOIN
                      dbo.PaymentItemParametars ON dbo.CustomerFinancialState.IdPriceCatalog = dbo.PaymentItemParametars.Id LEFT OUTER JOIN
                      dbo.Customers INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.Customers.Id = dbo.CustomerVehiclesRelations.IdCustomer INNER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id ON 
                      dbo.CustomerFinancialState.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id
 WHERE dbo.CustomerFinancialState.Active = 1 and dbo.PaymentItemParametars.active=1
and dbo.CustomerFinancialState.IdCustomerVehicleRelation=@IdCustomerVehicleRelation
