		@Suffocation bit,
		@Hook bit,
		@Vitlo bit,
		@VerticalBurdenOnTheSeat bit,
		@VerticalBurdenOnTheSeatNote nvarchar(250),
		@HologationSertificateNumber nvarchar(100),
		@NoiseStatic real,
		@NoiseMovment real,
		@CO real,
		@HC real,
		@NOx real,
		@HCNOx real,
		@Blackening nvarchar(20),
		@Pinpoints nvarchar(20),
		@CO2 real,
		@FuelConsumption nvarchar(20),
		@CapacityFuelTank real,
		@Note nvarchar(500),
		@IsSocialNotPrivate bit,
		@ForPrivateTransportNotPublic bit,
		@TNG bit,
		@VehicleModelAdding nvarchar(200),
		@NewId bigint output,
		@newLastChanged timestamp output
AS
    INSERT INTO [Vehicles]
		(
		IdVehicleBodyType,
		IdVehicleCategories,
		IdEngineType,
		IdEnginePowerSource,
		IdEngineSecondPowerSource,
		IdGearBox,
		IdBreakes,
		IdSupporting,
		IdVehicleModel,
		IdPrimaryColor,
		IdSecondaryColor,
		IdVehicleCategoryForPayments,
		IdEngineEcoProgram,
