		IdVehicleUse,
		ColorCode,
		EngineNumber,
		EnginePower,
		EngineTorque,
		EngineTorqueUnderGass,
		EngineWorkingCapacity,
		EnginePowerOutPut,
		ShellNumber,
		MakeDate,
		NumberOfDoors,
		NumberOfSeats,
		NumberOfStandingSeats,
		NumberOfLieingSeats,
		EmptyWaight,
		MaximunAllowedWaight,
		TrailerWaightWithBreak,
