		NumberOfAxis,
		PropulsionAxis,
		NumberOfWheels,
		NumberOfPropulsionWheels,
		VehicleSizeHight,
		VehicleSizeWidth,
		VehicleSizeLength,
		Suffocation,
		Hook,
		Vitlo,
		VerticalBurdenOnTheSeat,
		VerticalBurdenOnTheSeatNote,
		HologationSertificateNumber,
		NoiseStatic,
		NoiseMovment,
		CO,
		HC,
		NOx,
		HCNOx,
		Blackening,
		Pinpoints,
		CO2,
		FuelConsumption,
		CapacityFuelTank,
		Note,
		IsSocialNotPrivate,
		ForPrivateTransportNotPublic,
		TNG,
		VehicleModelAdding
		)
		VALUES
		(
		@IdVehicleBodyType,
		@IdVehicleCategories,
		@IdEngineType,
		@IdEnginePowerSource,
		@IdEngineSecondPowerSource,
		@IdGearBox,
		@IdBreakes,
		@IdSupporting,
		@IdVehicleModel,
		@IdPrimaryColor,
		@IdSecondaryColor,
		@IdVehicleCategoryForPayments,
		@IdEngineEcoProgram,
		@IdMadeCountry,
		@IdVehicleUse,
		@ColorCode,
		@EngineNumber,
