GO
SET QUOTED_IDENTIFIER ON
GO
-- Description: Procedura za zimanje site zapisi

CREATE PROC [dbo].[getCustomerVehiclesRelationsMinusTrafficLicence]
@IdRlationType as int
AS
SELECT   dbo.CustomerVehiclesRelations.Id,
		 dbo.CustomerVehiclesRelations.IdRelationType,
		 dbo.CustomerVehiclesRelations.IdCustomer, 
         dbo.CustomerVehiclesRelations.IdVehicle,
		 dbo.CustomerVehiclesRelations.StartDate,
		 dbo.CustomerVehiclesRelations.EndDate, 
         dbo.CustomerVehiclesRelations.BeginNote,
		 dbo.CustomerVehiclesRelations.TerminationNote,
		
         dbo.Customers.CustomerSurname,
		 dbo.Customers.CustomerFirstName,
		 dbo.Customers.MB,
		 dbo.Vehicles.EngineNumber,
		 dbo.Vehicles.ShellNumber, 
         dbo.CustomerVehiclesRelationTypes.RelationTypeName
FROM     dbo.CustomerVehiclesRelations INNER JOIN
         dbo.CustomerVehiclesRelationTypes ON dbo.CustomerVehiclesRelations.IdRelationType = dbo.CustomerVehiclesRelationTypes.Id LEFT OUTER JOIN
         dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id LEFT OUTER JOIN
         dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id
 WHERE dbo.CustomerVehiclesRelations.Active = 1 and dbo.CustomerVehiclesRelations.IdRelationType=@IdRlationType
except
SELECT     dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation as Id,dbo.CustomerVehiclesRelations.IdRelationType, dbo.CustomerVehiclesRelations.IdCustomer, dbo.CustomerVehiclesRelations.IdVehicle, 
                      dbo.CustomerVehiclesRelations.StartDate, dbo.CustomerVehiclesRelations.EndDate, dbo.CustomerVehiclesRelations.BeginNote, 
                      dbo.CustomerVehiclesRelations.TerminationNote,  dbo.Customers.CustomerSurname, 
                      dbo.Customers.CustomerFirstName, dbo.Customers.MB, dbo.Vehicles.EngineNumber, dbo.Vehicles.ShellNumber, 
                      dbo.CustomerVehiclesRelationTypes.RelationTypeName
FROM         dbo.CustomerVehiclesRelations LEFT OUTER JOIN
                      dbo.CustomerVehiclesRelationTypes ON dbo.CustomerVehiclesRelations.IdRelationType = dbo.CustomerVehiclesRelationTypes.Id LEFT OUTER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id LEFT OUTER JOIN
                      dbo.Vehicles ON dbo.CustomerVehiclesRelations.IdVehicle = dbo.Vehicles.Id RIGHT OUTER JOIN
                      dbo.DocumentsTrafficLicences ON dbo.CustomerVehiclesRelations.Id = dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation
 WHERE dbo.CustomerVehiclesRelations.Active = 1 and dbo.CustomerVehiclesRelations.IdRelationType=@IdRlationType
and dbo.DocumentsTrafficLicences.EndDate>getdate()
GO
