CREATE PROC [dbo].[updateVehicle]
		@Id bigint,
		@IdVehicleBodyType int,
		@IdVehicleCategories int,
		@IdEngineType int,
		@IdEnginePowerSource int,
		@IdEngineSecondPowerSource int,
		@IdGearBox int,
		@IdBreakes int,
		@IdSupporting int,
		@IdVehicleModel int,
		@IdPrimaryColor int,
		@IdSecondaryColor int,
		@IdVehicleCategoryForPayments int,
		@IdEngineEcoProgram int,
		@IdMadeCountry int,
		@IdVehicleUse int,
		@ColorCode nvarchar(50),
		@EngineNumber nvarchar(20),
		@EnginePower real,
		@EngineTorque nvarchar(250),
		@EngineTorqueUnderGass real,
		@EngineWorkingCapacity real,
		@EnginePowerOutPut real,
		@ShellNumber nvarchar(17),
		@MakeDate datetime,
		@NumberOfDoors int,
		@NumberOfSeats smallint,
		@NumberOfStandingSeats smallint,
		@NumberOfLieingSeats smallint,
		@EmptyWaight real,
		@MaximunAllowedWaight real,
		@TrailerWaightWithBreak nvarchar(20),
		@TrailerWaightWithoutBreak nvarchar(20),
		@NumberOfAxis int,
		@PropulsionAxis int,
		@NumberOfWheels int,
		@NumberOfPropulsionWheels int,
		@VehicleSizeHight real,
		@VehicleSizeWidth real,
		@VehicleSizeLength real,
		@Suffocation bit,
		@Hook bit,
		@Vitlo bit,
		@VerticalBurdenOnTheSeat bit,
		@VerticalBurdenOnTheSeatNote nvarchar(250),
		@HologationSertificateNumber nvarchar(100),
		@NoiseStatic real,
		@NoiseMovment real,
		@CO real,
		@HC real,
		@NOx real,
		@HCNOx real,
		@Blackening nvarchar(20),
		@Pinpoints nvarchar(20),
		@CO2 real,
		@FuelConsumption nvarchar(20),
		@CapacityFuelTank real,
		@Note nvarchar(500),
		@IsSocialNotPrivate bit,
		@ForPrivateTransportNotPublic bit,
		@TNG BIT,
		@VehicleModelAdding nvarchar(200),
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [Vehicles]
		SET
		IdVehicleBodyType = @idvehiclebodytype,
		IdVehicleCategories = @idvehiclecategories,
		IdEngineType = @idenginetype,
		IdEnginePowerSource = @idenginepowersource,
		IdEngineSecondPowerSource = @idenginesecondpowersource,
		IdGearBox = @idgearbox,
		IdBreakes = @idbreakes,
		IdSupporting = @idsupporting,
		IdVehicleModel = @idvehiclemodel,
		IdPrimaryColor = @idprimarycolor,
		IdSecondaryColor = @idsecondarycolor,
		IdVehicleCategoryForPayments = @idvehiclecategoryforpayments,
		IdEngineEcoProgram = @idengineecoprogram,
		IdMadeCountry = @IdMadeCountry,
		IdVehicleUse = @IdVehicleUse,
		ColorCode = @colorcode,
		EngineNumber = @enginenumber,
		EnginePower = @enginepower,
		EngineTorque = @enginetorque,
		EngineTorqueUnderGass = @enginetorqueundergass,
		EngineWorkingCapacity = @engineworkingcapacity,
		EnginePowerOutPut = @enginepoweroutput,
		ShellNumber = @shellnumber,
		MakeDate = @makedate,
		NumberOfDoors = @numberofdoors,
		NumberOfSeats = @numberofseats,
		NumberOfStandingSeats = @numberofstandingseats,
		NumberOfLieingSeats = @numberoflieingseats,
		EmptyWaight = @emptywaight,
		MaximunAllowedWaight = @maximunallowedwaight,
		TrailerWaightWithBreak = @trailerwaightwithbreak,
		TrailerWaightWithoutBreak = @trailerwaightwithoutbreak,
		NumberOfAxis = @numberofaxis,
		PropulsionAxis = @propulsionaxis,
		NumberOfWheels = @numberofwheels,
		NumberOfPropulsionWheels = @numberofpropulsionwheels,
		VehicleSizeHight = @vehiclesizehight,
		VehicleSizeWidth = @vehiclesizewidth,
		VehicleSizeLength = @vehiclesizelength,
		Suffocation = @suffocation,
		Hook = @hook,
		Vitlo = @vitlo,
		VerticalBurdenOnTheSeat = @verticalburdenontheseat,
		VerticalBurdenOnTheSeatNote = @verticalburdenontheseatnote,
		HologationSertificateNumber = @hologationsertificatenumber,
		NoiseStatic = @noisestatic,
		NoiseMovment = @noisemovment,
		CO = @co,
		HC = @hc,
		NOx = @nox,
		HCNOx = @hcnox,
		Blackening = @blackening,
		Pinpoints = @pinpoints,
		CO2 = @co2,
		FuelConsumption = @fuelconsumption,
		CapacityFuelTank = @capacityfueltank,
		Note = @note,
		IsSocialNotPrivate = @issocialnotprivate,
		ForPrivateTransportNotPublic = @forprivatetransportnotpublic,
		TNG = @TNG,
		VehicleModelAdding=@VehicleModelAdding
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [Vehicles] WHERE ID=@id
	RETURN
GO
