/****** Object:  StoredProcedure [dbo].[GetPaymentDocumentRataForFiscalPrintByIdRata]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[GetPaymentDocumentRataForFiscalPrintByIdRata]
	@idRata bigint
AS
SELECT     dbo.PaymentDocuments.Id AS IdPaymentDocument, dbo.PaymentDocuments.Storno, dbo.DogovorZaRati.Broj, dbo.DogovorZaRati.Datum, 
                      dbo.PaymentDocumentsRata.Price, dbo.PaymentDocumentsRata.Payed, dbo.PaymentDocumentsRata.DatePayed, dbo.PaymentDocumentsRata.Note, 
                      dbo.PaymentDocumentsRata.Id AS IdRata, dbo.PaymentDocuments.IdDogovor, dbo.Customers.CustomerFirstName, dbo.Customers.CustomerSurname,
                       dbo.Customers.MB, dbo.Customers.LivingAddressNumber, dbo.Streets.StreetName, dbo.Cities.CityName, dbo.PaymentDocuments.DocumentNumber, 
                      dbo.CustomerVehiclesRelations.IdVehicle, dbo.PaymentDocuments.IdPaymentType
FROM         dbo.PaymentDocuments INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.PaymentDocuments.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id LEFT OUTER JOIN
                      dbo.Cities ON dbo.Customers.IdLivingCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.DogovorZaRati ON dbo.PaymentDocuments.IdDogovor = dbo.DogovorZaRati.Id RIGHT OUTER JOIN
                      dbo.PaymentDocumentsRata ON dbo.PaymentDocuments.Id = dbo.PaymentDocumentsRata.IdPaymentDocument
                      WHERE
	(dbo.[PaymentDocuments].Active=1) AND
	(dbo.[PaymentDocumentsRata].Active=1) AND
	(dbo.[PaymentDocumentsRata].Id=@idRata)
GO
