/****** Object:  StoredProcedure [dbo].[PrintCustomer]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Name
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[PrintCustomer] 
	-- Add the parameters for the stored procedure here
	@id bigint
AS
SELECT     dbo.Customers.Id, dbo.Customers.MB, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.DateOfBirth, 
                      dbo.Customers.IsCompany, dbo.Customers.Occupation, dbo.Customers.WorksInCompany, dbo.Customers.BLK, dbo.Customers.PassportNumber, 
                      dbo.Customers.BrithAddressNumber, dbo.Customers.LivingAddressNumber, dbo.Customers.IdLivingAddress, 
                      dbo.Streets.StreetName AS StreetNameLiving, dbo.Customers.IdLivingCity, dbo.Customers.IdBirhCity, Cities_1.CityName AS CityNameBirh, 
                      Cities_1.CityZip AS CityZipBirh, dbo.Cities.CityName AS aCityNameLiving, dbo.Cities.CityZip AS CityZipLiving, dbo.Cities.IdCountry AS IdCountryLiving,
                       Countries_1.CountryShortName AS CountryShortNameLiving, Countries_1.CountryName AS CountryNameLiving, dbo.Cities.IdCommunityCode, 
                      dbo.Communities.CommunityCode AS CommunityCodeLiving, dbo.Communities.CommunityName AS CommunityNameLiving, 
                      Cities_1.IdCommunityCode AS IdCommunityCodeBirth, Communities_1.CommunityCode AS CommunityCodeBirth, 
                      Communities_1.CommunityName AS CommunityNameBirth, Cities_1.IdCountry AS IdCountryBirth, dbo.Countries.CountryName AS CountryNameBirth, 
                      dbo.Countries.CountryShortName AS CountryShortNameBirht, dbo.Customers.IdCitizenship, Countries_2.Citizenship, dbo.Customers.IdBusinessType, 
                      dbo.BusinessTypes.BusinessTypeCode, dbo.BusinessTypes.BusinessTypeDescription
FROM         dbo.Countries AS Countries_2 RIGHT OUTER JOIN
                      dbo.BusinessTypes RIGHT OUTER JOIN
                      dbo.Customers ON dbo.BusinessTypes.Id = dbo.Customers.IdBusinessType ON Countries_2.Id = dbo.Customers.IdCitizenship LEFT OUTER JOIN
                      dbo.Countries AS Countries_1 INNER JOIN
                      dbo.Cities ON Countries_1.Id = dbo.Cities.IdCountry INNER JOIN
                      dbo.Communities ON dbo.Cities.IdCommunityCode = dbo.Communities.Id ON dbo.Customers.IdLivingCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.Communities AS Communities_1 INNER JOIN
                      dbo.Cities AS Cities_1 ON Communities_1.Id = Cities_1.IdCommunityCode INNER JOIN
                      dbo.Countries ON Cities_1.IdCountry = dbo.Countries.Id ON dbo.Customers.IdBirhCity = Cities_1.Id LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id
WHERE dbo.Customers.Id= @id
GO
/****** Object:  StoredProcedure [dbo].[printCustomerPivotReport]    Script Date: 08/06/2009 13:09:56 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Ivan
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[printCustomerPivotReport]

AS
SELECT     dbo.Customers.MB, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.PhoneNumber, dbo.Customers.Fax, 
                      dbo.Streets.StreetName, dbo.Cities.CityName, dbo.Communities.CommunityCode, dbo.Communities.CommunityName, 
                      dbo.Customers.LivingAddressNumber, dbo.Customers.DateOfBirth, dbo.Customers.IsCompany, 
                      dbo.Customers.Occupation, dbo.Customers.WorksInCompany, dbo.BusinessTypes.BusinessTypeDescription, dbo.Customers.eMail, 
                      dbo.Customers.PassportNumber, dbo.Countries.CountryName
FROM         dbo.Countries INNER JOIN
                      dbo.Cities ON dbo.Countries.Id = dbo.Cities.IdCountry INNER JOIN
                      dbo.Communities ON dbo.Cities.IdCommunityCode = dbo.Communities.Id RIGHT OUTER JOIN
                      dbo.Customers ON dbo.Cities.Id = dbo.Customers.IdLivingCity LEFT OUTER JOIN
                      dbo.Streets ON dbo.Customers.IdLivingAddress = dbo.Streets.Id LEFT OUTER JOIN
                      dbo.BusinessTypes ON dbo.Customers.IdBusinessType = dbo.BusinessTypes.Id
where dbo.Customers.Active = 1
GO
