-- Description: Procedura za zimanje na red po Primaren kluc
 
CREATE PROC [dbo].[PrintCustomerById] 
	@id bigint
as
SELECT     dbo.Customers.MB, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName, dbo.Customers.IdLivingAddress, 
                      dbo.Customers.LivingAddressNumber, dbo.Customers.IdLivingCity, dbo.Customers.IdBirhCity, dbo.Customers.IdBirthAddress, 
                      dbo.Customers.BrithAddressNumber, dbo.Customers.IsCompany, dbo.Customers.Occupation, dbo.Customers.WorksInCompany, 
                      dbo.Customers.LastChanged, dbo.Streets.StreetName AS LivingStreet, dbo.Customers.IdBusinessType, 
                      dbo.BusinessTypes.BusinessTypeDescription, dbo.Cities.CityName AS LivingCity, dbo.Cities.IdCommunityCode, 
                      dbo.Communities.CommunityName AS LivingCommunity, dbo.Countries.CountryName AS LivingCountry, dbo.Customers.IdCitizenship, 
                      dbo.Countries.Citizenship
FROM         dbo.Streets RIGHT OUTER JOIN
                      dbo.Customers ON dbo.Streets.Id = dbo.Customers.IdLivingAddress LEFT OUTER JOIN
                      dbo.Cities INNER JOIN
                      dbo.Communities ON dbo.Cities.IdCommunityCode = dbo.Communities.Id INNER JOIN
                      dbo.Countries ON dbo.Cities.IdCountry = dbo.Countries.Id ON dbo.Customers.IdLivingCity = dbo.Cities.Id LEFT OUTER JOIN
                      dbo.BusinessTypes ON dbo.Customers.IdBusinessType = dbo.BusinessTypes.Id
WHERE ( dbo.Customers.Id = @id) AND ( dbo.Customers.Active = 1)
GO
