			 dbo.Customers.DateOfBirth,
			 dbo.Cities.CityName, 
             dbo.Countries.CountryName,
			 dbo.Streets.StreetName,
			 dbo.Communities.CommunityName
FROM         dbo.Countries INNER JOIN dbo.Cities 
			ON dbo.Countries.Id = dbo.Cities.IdCountry 
			INNER JOIN dbo.Communities 
			ON dbo.Cities.IdCommunityCode = dbo.Communities.Id
			RIGHT OUTER JOIN dbo.Customers 
			ON dbo.Cities.Id = dbo.Customers.IdLivingCity 
			LEFT OUTER JOIN dbo.Streets 
			ON dbo.Customers.IdLivingAddress = dbo.Streets.Id
 WHERE  dbo.Customers.Active = 1 and dbo.Customers.IsCompany = @isCompany
GO
