CREATE PROC [dbo].[getDocumentsTrafficLicencesNumberByIdVehicle]
@idVehicle bigint
AS
SELECT     dbo.DocumentsTrafficLicences.TrafficLicenceNumber
FROM         dbo.DocumentsTrafficLicences INNER JOIN
                      dbo.CustomerVehiclesRelationTypes INNER JOIN
                      dbo.CustomerVehiclesRelations ON dbo.CustomerVehiclesRelationTypes.Id = dbo.CustomerVehiclesRelations.IdRelationType ON 
                      dbo.DocumentsTrafficLicences.IdCustomerVehicleRelation = dbo.CustomerVehiclesRelations.Id
where dbo.CustomerVehiclesRelations.IdVehicle = @idVehicle
		and dbo.DocumentsTrafficLicences.EndDate > getdate()
		and dbo.CustomerVehiclesRelationTypes.IsOwner = 1 
		and dbo.DocumentsTrafficLicences.Active = 1
GO
