CREATE PROCEDURE [dbo].[getVehicleCurrentOwner]
	@idVehicle bigint
AS
SELECT     TOP (1) dbo.CustomerVehiclesRelations.IdCustomer, dbo.Customers.MB, dbo.Customers.CustomerSurname, dbo.Customers.CustomerFirstName
FROM         dbo.CustomerVehiclesRelations INNER JOIN
                      dbo.Customers ON dbo.CustomerVehiclesRelations.IdCustomer = dbo.Customers.Id inner join
	dbo.CustomerVehiclesRelationTypes ON dbo.CustomerVehiclesRelations.IdRelationType = dbo.CustomerVehiclesRelationTypes.Id
WHERE
	([CustomerVehiclesRelations].IdVehicle = @idVehicle) AND
	(dbo.CustomerVehiclesRelations.Active = 1) and
	(dbo.CustomerVehiclesRelationTypes.IsOwner = 1) and 
	(dbo.CustomerVehiclesRelations.EndDate is null or dbo.CustomerVehiclesRelations.EndDate>getdate())
ORDER BY [CustomerVehiclesRelations].EndDate DESC
GO
