CREATE PROC [dbo].[getCustomerVehiclesRelationIdByCustomerAndVehicle] 
	@idCustomer bigint,
	@idVehicle as bigint
AS
if @idVehicle=0
begin 
	SELECT 
        [CustomerVehiclesRelations].Id
    FROM   [CustomerVehiclesRelations] inner join [CustomerVehiclesRelationTypes]
		on [CustomerVehiclesRelations].IdRelationType=[CustomerVehiclesRelationTypes].Id
	WHERE ([CustomerVehiclesRelations].IdCustomer = @idCustomer) AND
		 ([CustomerVehiclesRelationTypes].IsCustomerOnly = 1) and
		 ([CustomerVehiclesRelations].Active = 1) 
		and ([CustomerVehiclesRelations].isnull(EndDate,-10)=-10)
		and [CustomerVehiclesRelations].StartDate<getdate()
end
else
begin
    SELECT 
        Id
    FROM   [CustomerVehiclesRelations]
	WHERE (IdCustomer = @idCustomer) AND
		(IdVehicle=@idVehicle) and
		 (Active = 1) and (isnull(EndDate,-10)=-10)
		and [CustomerVehiclesRelations].StartDate<getdate()
end
