    UPDATE [Requests]
	SET
		Active=0
	WHERE ID=@id
    UPDATE CustomerFinancialState
	SET
		Active=0
	WHERE IdDocument=@id
    UPDATE [Request.PaymentProof]
	SET
		Active=0
	WHERE IdRequest=@id
    UPDATE [Request.VehicleOwnershipProofs]
	SET
		Active=0
	WHERE IdRequest=@id
