CREATE PROC [dbo].[getVehicleRegistrationByIdVehicleList]
	@id bigint
AS
SELECT     
	dbo.[Vehicle.Registrations].Id,
	dbo.[Vehicle.Registrations].IdVehicle,
	dbo.[Vehicle.Registrations].IdRegistrationIssuer, 
	dbo.[RegistrationIssuers].IssuerName,
	dbo.[Vehicle.Registrations].RegistrationNumber,
	dbo.[Vehicle.Registrations].DateOfRegistration,
	dbo.[Vehicle.Registrations].DateRegistrationValidTill, 
	dbo.[Vehicle.Registrations].PlaceOfRegistration,
	dbo.[Vehicle.Registrations].LastChanged
FROM         
	dbo.[Vehicle.Registrations] INNER JOIN
	dbo.RegistrationIssuers ON dbo.[Vehicle.Registrations].IdRegistrationIssuer = dbo.RegistrationIssuers.Id
WHERE
	(dbo.[Vehicle.Registrations].IdVehicle = @id)
	AND (dbo.[Vehicle.Registrations].Active = 1)
GO
