SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[TehnicalExamPassed]
		@IdCustomerVehicleRelation bigint,
		@IdTehnicalExam bigint
as

if ((select VehicleIsRight from DocumentsTehnicalExamsReports where id = @IdTehnicalExam and ValidTillDate>getdate())=1)
begin
 UPDATE Requests SET IdTechnicalExamReport = @IdTehnicalExam
 WHERE (IdCustomerVehicleRelation=@IdCustomerVehicleRelation) and (Active=1)
end
GO
