CREATE PROC [dbo].[updateDocumentsTrafficLicenceSetEndDtae]
		@IdCustomerVehicleRelation bigint,
		@docTypeOption int		
AS
if ((select VehicleDeleted from DocumentTypesOptions where Id=@docTypeOption)=1)
begin
    UPDATE [DocumentsTrafficLicences]
		SET
			EndDate=getdate()
	WHERE ((IdCustomerVehicleRelation=@IdCustomerVehicleRelation) AND (EndDate>getdate()) and (Active=1))
end
GO
