CREATE PROCEDURE [dbo].[updatePaymentDocumentsDetailFinace] 
	-- Add the parameters for the stored procedure here
	@idPriceCatalog int, 
	@idCustomerVehicleRelation bigint
AS
declare @idFinance bigint
set @idFinance = (SELECT TOP (1) Id FROM CustomerFinancialState
				  WHERE (IdPriceCatalog=@idPriceCatalog AND IdCustomerVehicleRelation=@idCustomerVehicleRelation and Payed=1)
				  ORDER BY Id DESC)

if @idFinance is not null
	update CustomerFinancialState SET Payed=0 WHERE Id=@idFinance
GO
