CREATE PROC [dbo].[insertFinancialStatePriceCatalogForTehnicalExams]
@IdCustomerVehicleRelation bigint,
@IdDocument bigint,
@note nvarchar(150)
AS
declare @id int
declare @Price decimal
declare curs1 cursor for SELECT [PriceCatalog].Id,[PriceCatalog].Price
FROM dbo.[PriceCatalog] 
WHERE ([PriceCatalog].IsTehnicalExam = 1) AND ([PriceCatalog].Active = 1)
open curs1
fetch next from curs1 into @id,@Price

while @@fetch_status=0
BEGIN
   INSERT INTO [CustomerFinancialState]
		(
		IdCustomerVehicleRelation,
		IdDocument,
		IdDocumentTehnicalExam,
		IdDocumentsTrafficLicences,
		IdDocumentIternationalDriveingLicence,
		IdDocumentPermisions,
		IdPriceCatalog,
		Note,
		Price,
		Payed
		)
		VALUES
		(
		@IdCustomerVehicleRelation,
		0,		
		@IdDocument,
		0,
		0,
		0,
		@id,
		@note,
		@Price,
		0
		)
fetch next from curs1 into @id,@Price
END
close curs1
deallocate curs1
GO
