CREATE PROC [dbo].[updateCustomer]
		@Id bigint,
		@MB nvarchar(13),
		@CustomerSurname nvarchar(100),
		@CustomerFirstName nvarchar(100),
		@PhoneNumber nvarchar(20),
		@Fax nvarchar(20),
		@IdLivingAddress int,
		@LivingAddressNumber nvarchar(100),
		@IdLivingCity int,
		@IdBirhCity int,
		@IdBirthAddress int,
		@BrithAddressNumber nvarchar(100),
		@DateOfBirth datetime,
		@IdCitizenship int,
		@IsCompany bit,
		@Occupation nvarchar(50),
		@WorksInCompany nvarchar(150),
		@IdBusinessType int,
		@eMail nvarchar(100),
		@PassportNumber nvarchar(100),
		@BLK nvarchar(50),
		@CanSendNotifications bit,
		@TaxNumber nvarchar(50),
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [Customers]
		SET
		MB = @mb,
		CustomerSurname = @customersurname,
		CustomerFirstName = @customerfirstname,
		PhoneNumber = @phonenumber,
		Fax = @fax,
		IdLivingAddress = @idlivingaddress,
		LivingAddressNumber = @livingaddressnumber,
		IdLivingCity = @idlivingcity,
		IdBirhCity = @idbirhcity,
		IdBirthAddress = @idbirthaddress,
		BrithAddressNumber = @brithaddressnumber,
		DateOfBirth = @dateofbirth,
		IdCitizenship = @idcitizenship,
		IsCompany = @iscompany,
		Occupation = @occupation,
		WorksInCompany = @worksincompany,
		IdBusinessType = @idbusinesstype,
		eMail = @email,
		PassportNumber = @passportnumber,
		BLK = @blk,
		CanSendNotifications = @cansendnotifications,
		TaxNumber = @TaxNumber
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [Customers] WHERE ID=@id
	RETURN
GO
