-- =============================================
-- Author:		Ivan
-- Create date: 
-- Description:	
-- =============================================
CREATE PROCEDURE [dbo].[existsPremision] 
	-- Add the parameters for the stored procedure here
	@idCustomer bigint,
	@idOwner bigint
AS
SELECT
	dbo.DocumentsPermisions.Id
FROM
	dbo.DocumentsPermisions 
WHERE
	(dbo.DocumentsPermisions.Active = 1) and
	(dbo.DocumentsPermisions.IdCustomerVehicleRelation=@idCustomer) and
	(dbo.DocumentsPermisions.IdCustomerVehicleRelationOwner=@idOwner) and
	(dbo.DocumentsPermisions.ValidTillDate is null or dbo.DocumentsPermisions.ValidTillDate>getdate())
GO
