CREATE PROC [dbo].[updatePaymentDocumentsDetail]
		@Id bigint,
		@IdPaymentDocuments bigint,
		@IdPriceCatalog int,
		@Price money,
		@DDV real,
		@Note nvarchar(150),
		@PrePayed bit,
		@NotePrePayed nvarchar(150),
		@Discount real,
		@LastChanged timestamp,
		@newLastChanged timestamp output
AS
    UPDATE [PaymentDocumentsDetails]
		SET
		IdPaymentDocuments = @idpaymentdocuments,
		IdPriceCatalog = @idpricecatalog,
		Price = @price,
		DDV = @ddv,
		Note = @note,
		PrePayed = @prepayed,
		NotePrePayed = @noteprepayed,
		Discount = @discount
	WHERE ID=@id AND LastChanged=@lastChanged
  IF @@ROWCOUNT = 0
    RAISERROR('Redot e edituvan od drug korisnik', 16, 1)  
	
	SELECT @newLastChanged = LastChanged 
	FROM [PaymentDocumentsDetails] WHERE ID=@id
	RETURN
GO
